//! Chunk 51, finding r4#2: a stranger pays the contract three UTxOs of
//! 2^63 − 1 of one junk token, each under a fresh re-randomization of the
//! user's register (the register sits on chain beside every Seedelf). The
//! user's key owns all three, so every scan of the user's UTxOs takes them.
//! That must not stop `sweep --all` from sending what the user holds: what
//! one transaction can't hold together may stay for the next run, as
//! `utxos::fitting` leaves it, but the user's own ADA and tokens must go.
//!
//! `balance` (balance.rs:36-39) totals the same owned rows with the same
//! `utxos::assets_of`, but its module is `pub(crate)`, so no integration test
//! can run it. This test prints what that call returns on these rows.
//!
//! Drives the real `sweep --all` run against the CLI's offline mock Koios,
//! reusing `tests/cli/harness.rs` as is.

#[path = "cli/harness.rs"]
mod harness;

use harness::*;
use seedelf_cli::commands::sweep::{SweepArgs, run};
use seedelf_core::utxos;

#[tokio::test]
async fn sweep_all_still_goes_when_a_stranger_pays_the_users_register_tokens_past_a_u64() {
    let mut scenario = Scenario::start().await;

    // The user's own: 100 ₳, and 5 ₳ with 1,000 tokens bought.
    let bought = ("bb".repeat(28), hex::encode("BOUGHT"), 1_000);
    // The stranger's junk: three UTxOs of 2^63 − 1 of one token, 1.5 ₳
    // each, each under a fresh re-randomization of the user's register.
    let junk = ("cc".repeat(28), hex::encode("JUNK"), i64::MAX as u64);
    let mut rows = vec![
        wallet_utxo(scenario.scalar, 1, 100_000_000, &[]),
        wallet_utxo(scenario.scalar, 2, 5_000_000, std::slice::from_ref(&bought)),
    ];
    rows.extend(
        (3..=5).map(|n| wallet_utxo(scenario.scalar, n, 1_500_000, std::slice::from_ref(&junk))),
    );

    // What balance.rs:36-39 totals: every owned row that holds no Seedelf.
    let owned = utxos::collect_all_wallet_utxos(scenario.scalar, &seedelf_policy(), rows.clone())
        .expect("the scan");
    assert_eq!(
        owned.len(),
        5,
        "the stranger's rows are the user's: the user's key owns each register"
    );
    match utxos::assets_of(owned) {
        Ok((lovelace, tokens)) => eprintln!(
            "balance.rs:39 totals {lovelace} lovelace and {} tokens",
            tokens.len()
        ),
        Err(e) => eprintln!("balance.rs:39 stops on these rows: Error: {e:#}"),
    }

    scenario.mount_credential_utxos(rows).await;
    scenario.mount_evaluate(5).await;
    scenario.mount_collateral().await;
    scenario.mount_submit().await;

    run(
        SweepArgs {
            address: Some(external_address_bech32()),
            lovelace: None,
            all: true,
            assets: vec![],
            ada_handle: None,
            utxos: None,
        },
        PREPROD,
        VARIANT,
    )
    .await
    .expect("sweep --all should still send the user's own UTxOs");

    let params = protocol_params().await;
    let tx = decode_tx(&scenario.submitted_cbor().await);
    assert_sound_transaction(&tx, &scenario, &params);
    assert!(
        tx.inputs.contains(&(tx_hash(1), 0)),
        "the user's 100 ₳ UTxO should be swept"
    );
    assert!(
        tx.inputs.contains(&(tx_hash(2), 0)),
        "the user's bought tokens should be swept"
    );
    assert!(
        tx.outputs.iter().all(|o| o.address == external_address()),
        "sweep --all sends everything it spends to the address"
    );
}

//! Chunk 51, finding r4#4: a submit the CLI can't confirm mustn't read as a
//! plain refusal. When Koios's gateway answers a 5xx, a 2xx the CLI can't
//! read, or nothing within the client's 30 s timeout (seedelf-koios's
//! koios.rs:19), the node may already hold the transaction: the web wallet
//! calls all three "maybe sent" (koios.ts's `KoiosBusyError`). So what the
//! CLI prints must name the transaction it sent, so the user can look for it
//! before running the command again, and mustn't call it rejected.
//!
//! Drives the real `transfer` run against the CLI's offline mock Koios,
//! reusing `tests/cli/harness.rs` as is. What's checked is the error `lib.rs`
//! prints (`Error: {err:#}`). The timeout case waits out the client's 30 s.
//! A second run once the first has landed is observed too, not asserted: it
//! pays the same Seedelf again.

#[path = "cli/harness.rs"]
mod harness;

use std::time::Duration;

use blstrs::Scalar;
use seedelf_cli::commands::transfer::{TransforArgs, run};
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::UtxoResponse;
use serde_json::json;
use wiremock::matchers::{method, path};
use wiremock::{Mock, ResponseTemplate};

use harness::*;

/// The payment: 500 ₳ to another person's Seedelf.
const PAY: u64 = 500_000_000;

fn pay_once() -> TransforArgs {
    TransforArgs {
        seedelfs: vec![SAMPLE_SEEDELF.to_string()],
        lovelaces: Some(vec![PAY]),
        assets: vec![],
        utxos: None,
    }
}

/// What a first run left: the words the CLI printed, the id and CBOR of the
/// transaction it sent to Koios, and the two people's keys.
struct FirstRun {
    printed: String,
    sent_id: String,
    sent_cbor: String,
    payer: Scalar,
    recipient: Scalar,
}

/// The payer holds two UTxOs of 600 ₳ and pays 500 ₳ to the recipient's
/// Seedelf; Koios takes the transaction and answers its submit with `answer`.
async fn first_run(answer: ResponseTemplate) -> FirstRun {
    let mut scenario = Scenario::start().await;
    let recipient = random_scalar();
    scenario
        .mount_credential_utxos(vec![
            wallet_utxo(scenario.scalar, 1, 600_000_000, &[]),
            wallet_utxo(scenario.scalar, 2, 600_000_000, &[]),
            seedelf_utxo(recipient, 3, 1_500_000, SAMPLE_SEEDELF),
        ])
        .await;
    scenario.mount_evaluate(1).await;
    scenario.mount_collateral().await;
    Mock::given(method("POST"))
        .and(path("/api/v1/submittx"))
        .respond_with(answer)
        .mount(&scenario.server)
        .await;

    let err = run(pay_once(), PREPROD, VARIANT)
        .await
        .expect_err("Koios never confirmed the submit, and the mock has no tx_status");
    let sent_cbor = scenario.submitted_cbor().await;
    let sent = hex::decode(&sent_cbor).expect("tx cbor hex");
    let sent_id = hex::encode(seedelf_core::build::tx_id(&sent).expect("tx id"));
    FirstRun {
        printed: format!("Error: {err:#}"),
        sent_id,
        sent_cbor,
        payer: scenario.scalar,
        recipient,
    }
}

/// The same command run again once the first transaction has landed: Koios
/// no longer lists the UTxO it spent, and lists its two outputs, the 500 ₳
/// at the recipient's register among them. Returns what the second run's
/// transaction pays the recipient.
async fn rerun_after_landing(first: &FirstRun) -> Result<u64, String> {
    let mut scenario = Scenario::start().await;
    scenario.scalar = first.payer;
    seedelf_cli::setup::inject_wallet_scalar(Some(first.payer));

    let landed = decode_tx(&first.sent_cbor);
    let mut rows: Vec<UtxoResponse> = (1..=2)
        .filter(|n| !landed.inputs.contains(&(tx_hash(*n), 0)))
        .map(|n| wallet_utxo(first.payer, n, 600_000_000, &[]))
        .collect();
    for (index, output) in landed.outputs.iter().enumerate() {
        let Some(register) = output.register.clone() else {
            continue;
        };
        let mut row = wallet_utxo(first.payer, 0, output.lovelace, &[]);
        row.tx_hash = first.sent_id.clone();
        row.tx_index = index as u64;
        row.inline_datum = Some(register_inline_datum(&register));
        rows.push(row);
    }
    rows.push(seedelf_utxo(first.recipient, 3, 1_500_000, SAMPLE_SEEDELF));
    scenario.mount_credential_utxos(rows).await;
    scenario.mount_evaluate(1).await;
    scenario.mount_collateral().await;
    scenario.mount_submit().await;

    run(pay_once(), PREPROD, VARIANT)
        .await
        .map_err(|e| format!("{e:#}"))?;
    let again = decode_tx(&scenario.submitted_cbor().await);
    Ok(again
        .outputs
        .iter()
        .filter(|o| {
            o.register
                .as_ref()
                .is_some_and(|r| r.is_owned(first.recipient).unwrap_or(false))
        })
        .map(|o| o.lovelace)
        .sum())
}

#[tokio::test]
async fn a_submit_koios_never_confirmed_names_the_transaction_it_sent() {
    // A gateway's "the instance behind me didn't answer in time".
    let gateway_504 = ResponseTemplate::new(504).set_body_raw(
        "<html><body><h1>504 Gateway Time-out</h1></body></html>",
        "text/html",
    );
    // 202 is Koios's success; this one's body stops before the id's closing quote.
    let cut_off_202 = ResponseTemplate::new(202).set_body_raw("\"5f2b", "application/json");
    // Koios takes it, and answers after the client's 30 s timeout.
    let too_slow = ResponseTemplate::new(202)
        .set_body_json(json!(tx_hash(999)))
        .set_delay(Duration::from_secs(31));

    let mut runs: Vec<(&str, FirstRun)> = Vec::new();
    for (case, answer) in [
        ("a 504 from Koios's gateway", gateway_504),
        ("a 202 whose body is cut off", cut_off_202),
        ("no answer within 30 s", too_slow),
    ] {
        runs.push((case, first_run(answer).await));
    }

    // The consequence the user meets after reading "rejected" and running it again.
    let again = match rerun_after_landing(&runs[0].1).await {
        Ok(paid) => format!(
            "run again once the first landed, the CLI paid the same Seedelf {paid} lovelace more \
             (the first paid {PAY})"
        ),
        Err(e) => format!("run again once the first landed, the CLI stopped: {e}"),
    };
    eprintln!("{again}");

    let wrong: Vec<String> = runs
        .iter()
        .filter(|(_, r)| !r.printed.contains(&r.sent_id) || r.printed.to_lowercase().contains("reject"))
        .map(|(case, r)| format!("{case}: printed {:?}; the transaction sent was {}", r.printed, r.sent_id))
        .collect();
    assert!(
        wrong.is_empty(),
        "a submit Koios never confirmed must name the transaction sent, and not as rejected:\n{}\n\
         and {again}",
        wrong.join("\n")
    );
}

//! Chunk 51, finding r2a#1 (also r2b#1, w1b#1's first case).
//!
//! A key address whose stake part is a script (CIP-19 header type 2:
//! `addr1y…`, `addr_test1y…`) is an ordinary payee: the ledger takes an
//! output there with no datum, and only its payment key can spend it, so
//! nothing paid to it can be locked. `build::is_payable_address` refuses it
//! today, because `is_not_a_script` (address.rs:63) uses Pallas's
//! `has_script`, which counts the stake part too. Public Send, Make public,
//! contacts and handles all go through that predicate.
//!
//! The right behaviour, asserted here: it's payable on its own network, and
//! a public Send of 3 ₳ pays it exactly, with no datum.

use pallas_addresses::{
    Address, Network, ScriptHash, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
};
use pallas_traverse::MultiEraTx;
use seedelf_core::build::{self, AccountAmount};
use seedelf_core::staking::Staking;
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_koios::koios::{ProtocolParameters, UtxoResponse};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

/// Someone else's payment key (account 1 of the phrase), staked by a script
/// (a multisig's native stake script, say), read back from bech32 as a user
/// pastes it.
fn key_staked_by_a_script(network: Network) -> Address {
    let payee = CardanoAccount::from_phrase(PHRASE, 1).unwrap();
    let text = Address::from(ShelleyAddress::new(
        network,
        ShelleyPaymentPart::Key(payee.key_hash(Role::Receive, 0).unwrap()),
        ShelleyDelegationPart::Script(ScriptHash::new([9; 28])),
    ))
    .to_bech32()
    .unwrap();
    Address::from_bech32(&text).unwrap()
}

#[test]
fn a_key_address_whose_stake_part_is_a_script_is_paid() {
    let preprod = key_staked_by_a_script(Network::Testnet);
    let mainnet = key_staked_by_a_script(Network::Mainnet);
    assert!(preprod.to_bech32().unwrap().starts_with("addr_test1y"));
    assert!(mainnet.to_bech32().unwrap().starts_with("addr1y"));

    // Public Send (`account_send`): 3 ₳ from a 30 ₳ UTxO at the account's 0/0.
    let rows: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/epoch_params.json")).unwrap();
    let params = ProtocolParameters::from_koios(&rows[0]).unwrap();
    let account = CardanoAccount::from_phrase(PHRASE, 0).unwrap();
    let change = account.base_address(true, Role::Receive, 0).unwrap();
    let available = vec![UtxoResponse {
        tx_hash: hex::encode([1u8; 32]),
        tx_index: 0,
        address: change.to_bech32().unwrap(),
        value: "30000000".to_string(),
        payment_cred: hex::encode(account.key_hash(Role::Receive, 0).unwrap()),
        asset_list: Some(Vec::new()),
        ..Default::default()
    }];
    let send = |to: &Address| {
        build::account_send(
            &params,
            &available,
            AccountAmount::Lovelace(3_000_000),
            &[],
            to,
            true,
            &change,
            &Staking::none(),
            None,
        )
    };

    // The control: the same payee's key, staked by a key, is paid.
    let plain = CardanoAccount::from_phrase(PHRASE, 1)
        .unwrap()
        .base_address(true, Role::Receive, 0)
        .unwrap();
    assert!(build::is_payable_address(&plain, true));
    assert!(send(&plain).is_ok(), "the fixture pays a plain key address");

    // Only the stake part differs.
    let payable = (
        build::is_payable_address(&preprod, true),
        build::is_payable_address(&mainnet, false),
    );
    let sent = send(&preprod);
    assert!(
        payable == (true, true) && sent.is_ok(),
        "is_payable_address (preprod, mainnet): {payable:?}; public Send of 3 ₳: {:?}",
        sent.as_ref().err().map(|e| e.to_string())
    );

    let built = sent.unwrap();
    let tx = MultiEraTx::decode(&built.tx.tx_bytes.0).unwrap();
    let paid: Vec<_> = tx
        .outputs()
        .into_iter()
        .filter(|o| o.address().unwrap() == preprod)
        .collect();
    assert_eq!(paid.len(), 1, "one output pays it");
    assert_eq!(paid[0].value().coin(), 3_000_000);
    assert!(paid[0].datum().is_none(), "a key address needs no datum");
}

//! Chunk 51, finding r1#1: the CLI reads the wallet contract in `?offset=N`
//! pages (seedelf-koios `credential_utxos`), so a UTxO spent ahead of a page
//! boundary between two page requests moves every later row up by one, and
//! the row at the boundary is never read.
//!
//! The mock stands in for Koios's PostgREST: at most 1,000 rows a request
//! (max-rows), with `offset`, `limit`, `order` and the `or=`/`and=` filters
//! on `tx_hash`, `tx_index` and `block_height`, and with no `order` the rows
//! in the order they were added. A block spends another user's UTxO from the
//! first page between the first and second requests. The wallet's one UTxO,
//! 25 ADA, is the first row of the second page. A read that pages by keyset,
//! as koios.ts `paged()` does, gets it.

use std::collections::BTreeMap;

use seedelf_core::address::wallet_contract;
use seedelf_core::constants::get_config;
use seedelf_core::utxos::{assets_of, collect_all_wallet_utxos, get_credential_utxos};
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::override_endpoints;
use serde_json::{Value, json};
use wiremock::matchers::{method, path};
use wiremock::{Mock, MockServer, Request, Respond, ResponseTemplate};

/// Koios's max-rows.
const MAX_ROWS: usize = 1000;
const PREPROD: bool = true;

/// A distinct 32-byte transaction hash for row `i` (splitmix64), so the order
/// the rows were added in isn't their hash order.
fn hash_of(i: u64) -> String {
    (1..=4u64)
        .map(|k| {
            let mut z = i.wrapping_add(k.wrapping_mul(0x9E37_79B9_7F4A_7C15));
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            format!("{:016x}", z ^ (z >> 31))
        })
        .collect()
}

/// A wallet-contract UTxO as Koios's `credential_utxos` lists it.
fn row(tx_hash: &str, register: &Register, lovelace: u64, cred: &str, address: &str) -> Value {
    json!({
        "tx_hash": tx_hash,
        "tx_index": 0,
        "address": address,
        "value": lovelace.to_string(),
        "stake_address": null,
        "payment_cred": cred,
        "epoch_no": 290,
        "block_height": 3_000_000,
        "block_time": 1_700_000_000,
        "datum_hash": null,
        "inline_datum": {"bytes": hex::encode(register.to_vec().expect("register cbor")), "value": null},
        "reference_script": null,
        "asset_list": [],
        "is_spent": false
    })
}

/// A PostgREST condition on a row.
enum Cond {
    Cmp(String, String, String),
    Any(Vec<Cond>),
    All(Vec<Cond>),
}

fn cmp_of(col: &str, op_value: &str) -> Result<Cond, String> {
    let (op, value) = op_value
        .split_once('.')
        .ok_or_else(|| format!("unreadable filter {col}={op_value}"))?;
    if !["tx_hash", "tx_index", "block_height"].contains(&col) {
        return Err(format!("the mock doesn't filter on {col}"));
    }
    if !["eq", "neq", "gt", "gte", "lt", "lte"].contains(&op) {
        return Err(format!("the mock doesn't know the operator {op}"));
    }
    Ok(Cond::Cmp(col.into(), op.into(), value.into()))
}

/// `(a,b,…)` of a logic tree, each `col.op.value`, `or(…)` or `and(…)`.
fn tree_of(all: bool, list: &str) -> Result<Cond, String> {
    let inner = list
        .strip_prefix('(')
        .and_then(|s| s.strip_suffix(')'))
        .ok_or_else(|| format!("unreadable logic tree {list}"))?;
    let (mut items, mut depth, mut start) = (Vec::new(), 0, 0);
    for (i, c) in inner.char_indices() {
        match c {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                items.push(&inner[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    items.push(&inner[start..]);
    let conds = items
        .into_iter()
        .map(|item| {
            if let Some(rest) = item.strip_prefix("or") {
                tree_of(false, rest)
            } else if let Some(rest) = item.strip_prefix("and") {
                tree_of(true, rest)
            } else {
                let (col, op_value) = item
                    .split_once('.')
                    .ok_or_else(|| format!("unreadable condition {item}"))?;
                cmp_of(col, op_value)
            }
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(if all {
        Cond::All(conds)
    } else {
        Cond::Any(conds)
    })
}

fn order_of(a: &Value, b: &Value, col: &str) -> std::cmp::Ordering {
    match col {
        "tx_hash" => a[col].as_str().cmp(&b[col].as_str()),
        _ => a[col].as_u64().cmp(&b[col].as_u64()),
    }
}

fn holds(cond: &Cond, row: &Value) -> Result<bool, String> {
    Ok(match cond {
        Cond::Any(conds) => conds
            .iter()
            .map(|c| holds(c, row))
            .collect::<Result<Vec<_>, _>>()?
            .contains(&true),
        Cond::All(conds) => !conds
            .iter()
            .map(|c| holds(c, row))
            .collect::<Result<Vec<_>, _>>()?
            .contains(&false),
        Cond::Cmp(col, op, value) => {
            let ord = if col == "tx_hash" {
                row[col.as_str()]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(value.as_str())
            } else {
                let n: u64 = value
                    .parse()
                    .map_err(|_| format!("{col} isn't compared with a number: {value}"))?;
                row[col.as_str()].as_u64().unwrap_or_default().cmp(&n)
            };
            match op.as_str() {
                "eq" => ord.is_eq(),
                "neq" => ord.is_ne(),
                "gt" => ord.is_gt(),
                "gte" => ord.is_ge(),
                "lt" => ord.is_lt(),
                _ => ord.is_le(),
            }
        }
    })
}

/// What PostgREST answers for `request` over `rows`, in the order they were added.
fn page(rows: &[&Value], request: &Request) -> Result<Vec<Value>, String> {
    let (mut offset, mut limit) = (0usize, MAX_ROWS);
    let mut order: Vec<(String, bool)> = Vec::new();
    let mut conds: Vec<Cond> = Vec::new();
    for (key, value) in request.url.query_pairs() {
        match key.as_ref() {
            "offset" => offset = value.parse().map_err(|_| format!("bad offset {value}"))?,
            "limit" => limit = limit.min(value.parse().map_err(|_| format!("bad limit {value}"))?),
            "select" => {}
            "order" => {
                order = value
                    .split(',')
                    .map(|term| {
                        let mut parts = term.split('.');
                        let col = parts.next().unwrap_or_default().to_string();
                        (col, parts.next() == Some("desc"))
                    })
                    .collect()
            }
            "or" => conds.push(tree_of(false, &value)?),
            "and" => conds.push(tree_of(true, &value)?),
            col => conds.push(cmp_of(col, &value)?),
        }
    }
    let mut kept: Vec<&Value> = Vec::new();
    for row in rows {
        if conds
            .iter()
            .map(|c| holds(c, row))
            .collect::<Result<Vec<_>, _>>()?
            .iter()
            .all(|h| *h)
        {
            kept.push(row);
        }
    }
    kept.sort_by(|a, b| {
        order
            .iter()
            .fold(std::cmp::Ordering::Equal, |acc, (col, desc)| {
                acc.then_with(|| {
                    let ord = order_of(a, b, col);
                    if *desc { ord.reverse() } else { ord }
                })
            })
    });
    Ok(kept.into_iter().skip(offset).take(limit).cloned().collect())
}

/// Koios over the contract: `spent` leaves the set once the first request is answered.
struct Koios {
    cred: String,
    rows: Vec<Value>,
    spent: String,
    answered: std::sync::atomic::AtomicUsize,
}

impl Respond for Koios {
    fn respond(&self, request: &Request) -> ResponseTemplate {
        let body: Value = serde_json::from_slice(&request.body).unwrap_or(Value::Null);
        if body["_payment_credentials"] != json!([self.cred]) {
            return ResponseTemplate::new(400).set_body_string("not the contract's credential");
        }
        let after_block = self
            .answered
            .fetch_add(1, std::sync::atomic::Ordering::SeqCst)
            > 0;
        let live: Vec<&Value> = self
            .rows
            .iter()
            .filter(|r| !after_block || r["tx_hash"] != self.spent.as_str())
            .collect();
        match page(&live, request) {
            Ok(rows) => ResponseTemplate::new(200).set_body_json(rows),
            Err(why) => ResponseTemplate::new(400).set_body_string(why),
        }
    }
}

#[tokio::test]
async fn a_utxo_spent_between_two_pages_hides_no_other_utxo() {
    let config = get_config(1, PREPROD).expect("variant 1 config");
    let cred = hex::encode(config.contract.wallet_contract_hash);
    let address = wallet_contract(PREPROD, config.contract.wallet_contract_hash)
        .to_bech32()
        .expect("contract bech32");

    let user = random_scalar();
    let mine = Register::create(user)
        .and_then(Register::rerandomize)
        .expect("register");
    let theirs = Register::create(random_scalar())
        .and_then(Register::rerandomize)
        .expect("register");

    // 1,200 UTxOs at the contract, in the order they were added. The wallet's
    // one UTxO, 25 ADA, is the 1,001st: the first of the second page.
    const WALLET_AT: usize = 1000;
    const SPENT_AT: usize = 400;
    let rows: Vec<Value> = (0..1200u64)
        .map(|i| {
            let (register, lovelace) = if i as usize == WALLET_AT {
                (&mine, 25_000_000)
            } else {
                (&theirs, 2_000_000)
            };
            row(&hash_of(i), register, lovelace, &cred, &address)
        })
        .collect();
    let outpoint = |r: &Value| format!("{}#{}", r["tx_hash"].as_str().unwrap(), r["tx_index"]);
    let wallet_utxo = outpoint(&rows[WALLET_AT]);
    let spent = rows[SPENT_AT]["tx_hash"].as_str().unwrap().to_string();

    let server = MockServer::start().await;
    override_endpoints(Some(server.uri()), None);
    Mock::given(method("POST"))
        .and(path("/api/v1/credential_utxos"))
        .respond_with(Koios {
            cred: cred.clone(),
            rows: rows.clone(),
            spent: spent.clone(),
            answered: Default::default(),
        })
        .mount(&server)
        .await;

    // What balance.rs:34-39 reads and sums.
    let read = get_credential_utxos(config.contract.wallet_contract_hash, PREPROD)
        .await
        .expect("the contract's UTxOs");
    let owned = collect_all_wallet_utxos(user, &config.contract.seedelf_policy_id, read.clone())
        .expect("owned UTxOs");
    let (lovelace, _) = assets_of(owned).expect("balance");

    let mut seen: BTreeMap<String, usize> = BTreeMap::new();
    for utxo in &read {
        *seen
            .entry(format!("{}#{}", utxo.tx_hash, utxo.tx_index))
            .or_default() += 1;
    }
    // Every UTxO at the contract for the whole read, each once.
    let missing: Vec<String> = rows
        .iter()
        .filter(|r| r["tx_hash"] != spent.as_str())
        .map(outpoint)
        .filter(|o| !seen.contains_key(o))
        .collect();
    let repeated: Vec<&String> = seen
        .iter()
        .filter(|(_, n)| **n > 1)
        .map(|(o, _)| o)
        .collect();
    let asked: Vec<String> = server
        .received_requests()
        .await
        .unwrap_or_default()
        .iter()
        .map(|r| r.url.query().unwrap_or_default().chars().take(60).collect())
        .collect();

    assert!(
        missing.is_empty() && repeated.is_empty() && lovelace == 25_000_000,
        "a block spent {spent}#0 between the first and second requests ({asked:?}): \
         the read of {} rows missed {missing:?} (the wallet's 25 ADA UTxO is {wallet_utxo}) \
         and repeated {repeated:?}, so the CLI's balance is {lovelace} lovelace, not 25000000",
        read.len()
    );
}

//! Chunk 51, finding r1#2: the CLI's submit reads "Koios took the transaction
//! but never answered" as not sent.
//!
//! `seedelf_koios::koios::submit_tx` puts every outcome but a 2xx into two
//! errors: "Koios rejected the transaction" (any 4xx or 5xx) and "Failed to
//! submit transaction" (no answer at all). So a gateway 504, or the client's
//! own 30 s timeout, after Koios has the transaction reads the same as the
//! node refusing it, or as a connection that never opened, and the CLI prints
//! no transaction id. The transaction can still land, and `transfer` run again
//! once it has spends its change and pays the recipient a second time.
//!
//! Part 1 drives the real `transfer` against tests/cli's mock Koios (its
//! harness is included here unchanged) to show that, and checks only its own
//! preconditions. Part 2 is the assertion: `submit_tx`'s own words (its
//! outermost message, the one the CLI's `Error:` line starts with) for a
//! submit that may have gone through must not be the words it uses for one
//! that didn't. It fails today for both the 504 and the timeout.

#[path = "cli/harness.rs"]
mod harness;

use std::time::Duration;

use harness::*;
use pallas_traverse::MultiEraTx;
use seedelf_cli::commands::transfer::{TransforArgs, run};
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{UtxoResponse, override_endpoints, submit_tx};
use serde_json::json;
use wiremock::matchers::{method, path};
use wiremock::{Mock, MockServer, Request, Respond, ResponseTemplate};

/// What the user means to pay the stranger's Seedelf, once.
const PAID: u64 = 2_000_000;

/// HAProxy's own 504 page: Koios's gateway took the request, and the instance
/// behind it didn't answer in time.
const GATEWAY_504: &str =
    "<html><body><h1>504 Gateway Time-out</h1>\nThe server didn't respond in time.\n</body></html>\n";

/// A node's refusal, as Koios passes on cardano-submit-api's answer.
const NODE_REFUSAL: &str = r#"{"contents":{"contents":{"contents":{"era":"ShelleyBasedEraConway","error":["ConwayUtxowFailure (UtxoFailure (ValueNotConservedUTxO ...))"],"kind":"ShelleyTxValidationError"},"tag":"TxValidationErrorInCardanoMode"},"tag":"TxCmdTxSubmitValidationError"},"tag":"TxSubmitFail"}"#;

/// `credential_utxos` as Koios pages it: `rows` at offset 0, then nothing.
struct Rows(Vec<UtxoResponse>);

impl Respond for Rows {
    fn respond(&self, request: &Request) -> ResponseTemplate {
        let first = request
            .url
            .query_pairs()
            .all(|(k, v)| k != "offset" || v == "0");
        ResponseTemplate::new(200).set_body_json(if first { json!(self.0) } else { json!([]) })
    }
}

fn pay_the_stranger() -> TransforArgs {
    TransforArgs {
        seedelfs: vec![SAMPLE_SEEDELF.to_string()],
        lovelaces: Some(vec![PAID]),
        assets: vec![],
        utxos: None,
    }
}

/// Every transaction the mock's `submittx` was handed, in order, as hex.
async fn submitted(server: &MockServer) -> Vec<String> {
    server
        .received_requests()
        .await
        .expect("request recording is on")
        .iter()
        .filter(|r| r.url.path() == "/api/v1/submittx")
        .map(|r| hex::encode(&r.body))
        .collect()
}

/// What a submit came back with: its own words alone (an error's outermost
/// message, or an outcome's debug form, should a fix return one as `Ok`), and
/// all of it, as the CLI prints an error (`Error: {err:#}`).
struct Said {
    own: String,
    full: String,
}

fn said<T: std::fmt::Debug, E: std::fmt::Display>(outcome: Result<T, E>) -> Said {
    match outcome {
        Ok(v) => Said {
            own: format!("{v:?}"),
            full: format!("Ok({v:?})"),
        },
        Err(e) => Said {
            own: format!("{e}"),
            full: format!("{e:#}"),
        },
    }
}

/// `submit_tx` once, with `answer` mounted for this call alone.
async fn submit_answered(server: &MockServer, answer: ResponseTemplate, cbor: &str) -> Said {
    let _only_now = Mock::given(method("POST"))
        .and(path("/api/v1/submittx"))
        .respond_with(answer)
        .mount_as_scoped(server)
        .await;
    said(submit_tx(cbor.to_string(), PREPROD).await)
}

#[tokio::test]
async fn a_submit_that_may_have_gone_through_does_not_read_as_not_sent() {
    let mut scenario = Scenario::start().await;
    let stranger = random_scalar();
    let their_seedelf = seedelf_utxo(stranger, 2, 1_500_000, SAMPLE_SEEDELF);
    scenario
        .mount_credential_utxos(vec![
            wallet_utxo(scenario.scalar, 1, 10_000_000, &[]),
            their_seedelf.clone(),
        ])
        .await;
    scenario.mount_evaluate(1).await;
    scenario.mount_collateral().await;
    let to_stranger = |tx: &DecodedTx| -> u64 {
        tx.outputs
            .iter()
            .filter(|o| {
                o.register
                    .as_ref()
                    .is_some_and(|r| r.is_owned(stranger).unwrap_or(false))
            })
            .map(|o| o.lovelace)
            .sum()
    };

    // ---- Part 1: what the user lives through (shown, not asserted) ----

    // Koios takes the transaction, and its gateway answers 504.
    let gateway = Mock::given(method("POST"))
        .and(path("/api/v1/submittx"))
        .respond_with(ResponseTemplate::new(504).set_body_raw(GATEWAY_504, "text/html"))
        .mount_as_scoped(&scenario.server)
        .await;
    let first = said(run(pay_the_stranger(), PREPROD, VARIANT).await);
    drop(gateway);
    println!("run 1 ends with: {}", first.full);
    let sent = submitted(&scenario.server).await;
    assert_eq!(sent.len(), 1, "Koios was handed run 1's transaction");
    let first_cbor = sent[0].clone();
    let first_tx = decode_tx(&first_cbor);
    let first_hash = hex::encode(
        *MultiEraTx::decode(&hex::decode(&first_cbor).expect("hex"))
            .expect("transaction")
            .hash(),
    );
    println!(
        "run 1's transaction {first_hash}, which Koios had, pays the stranger {} lovelace",
        to_stranger(&first_tx)
    );

    // It lands: the contract now holds its outputs, not the UTxO it spent.
    let mut landed = vec![their_seedelf.clone()];
    for (i, output) in first_tx.outputs.iter().enumerate() {
        let mut row = wallet_utxo(scenario.scalar, 0, output.lovelace, &[]);
        row.tx_hash = first_hash.clone();
        row.tx_index = i as u64;
        row.inline_datum = Some(register_inline_datum(
            output.register.as_ref().expect("a contract output's register"),
        ));
        landed.push(row);
    }
    Mock::given(method("POST"))
        .and(path("/api/v1/credential_utxos"))
        .respond_with(Rows(landed))
        .with_priority(1)
        .mount(&scenario.server)
        .await;

    // The user runs the same transfer again, and Koios answers this time.
    let accepted = Mock::given(method("POST"))
        .and(path("/api/v1/submittx"))
        .respond_with(ResponseTemplate::new(202).set_body_json(json!(tx_hash(2))))
        .mount_as_scoped(&scenario.server)
        .await;
    let second = run(pay_the_stranger(), PREPROD, VARIANT).await;
    drop(accepted);
    match second {
        Ok(()) => {
            let second_tx = decode_tx(&submitted(&scenario.server).await[1]);
            let spends_first = second_tx.inputs.iter().any(|(h, _)| *h == first_hash);
            println!(
                "run 2 succeeds: spends run 1's change: {spends_first}; pays the stranger {} lovelace more: {} in all for one {PAID} payment",
                to_stranger(&second_tx),
                to_stranger(&first_tx) + to_stranger(&second_tx)
            );
        }
        Err(e) => println!("run 2 fails: Error: {e:#}"),
    }

    // ---- Part 2: the assertion, on submit_tx itself ----

    let refused = submit_answered(
        &scenario.server,
        ResponseTemplate::new(400).set_body_raw(NODE_REFUSAL, "application/json"),
        &first_cbor,
    )
    .await;
    let before = submitted(&scenario.server).await.len();
    let gateway_504 = submit_answered(
        &scenario.server,
        ResponseTemplate::new(504).set_body_raw(GATEWAY_504, "text/html"),
        &first_cbor,
    )
    .await;
    // Koios would answer 202 at 90 s; the client gives up first (at 30 s).
    let timed_out = submit_answered(
        &scenario.server,
        ResponseTemplate::new(202)
            .set_body_json(json!(first_hash))
            .set_delay(Duration::from_secs(90)),
        &first_cbor,
    )
    .await;
    let had = submitted(&scenario.server).await.len() - before;
    assert_eq!(had, 2, "Koios had the transaction in both of those");

    // A connection that never opened: nothing left the machine.
    let closed = std::net::TcpListener::bind("127.0.0.1:0").expect("a free port");
    let port = closed.local_addr().expect("its address").port();
    drop(closed);
    override_endpoints(
        Some(format!("http://127.0.0.1:{port}")),
        Some(scenario.server.uri()),
    );
    let never_left = said(submit_tx(first_cbor.clone(), PREPROD).await);
    override_endpoints(Some(scenario.server.uri()), Some(scenario.server.uri()));

    for (case, s) in [
        ("not sent, the node's refusal (400)", &refused),
        ("not sent, a connection never opened", &never_left),
        ("may have gone, a gateway 504 after Koios had it", &gateway_504),
        ("may have gone, the 30 s timeout after Koios had it", &timed_out),
    ] {
        println!("{case}: {}", s.full);
    }

    let wrong: Vec<String> = [
        ("a gateway 504", &gateway_504),
        ("the client's 30 s timeout", &timed_out),
    ]
    .into_iter()
    .filter_map(|(case, s)| {
        let like = if s.own == refused.own {
            "the node's refusal"
        } else if s.own == never_left.own {
            "a connection that never opened"
        } else {
            return None;
        };
        Some(format!(
            "{case} after Koios had the transaction reads as not sent, in the words of {like}: \"{}\"",
            s.full
        ))
    })
    .collect();
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

//! Chunk 51, finding r2a#2: `apart` ends its search at the first order grown
//! whole that's short (build.rs `Grown::Short if whole => { failed = false;
//! break; }`), on the premise "short with everything is short in any order"
//! (independent review M6). A UTxO whose tokens need more change than it
//! holds breaks that premise: everything together is short while a subset
//! pays. A payment the CLI's own order makes is then refused, against
//! build.rs's section comment and privacy.md ("It never refuses a payment the
//! CLI's order would make").
//!
//! The state: 20 ₳ made private (Own), two boxes back from Lovejoin, and a
//! stranger's payment of 200 tokens (one policy, 1-byte names) holding the
//! least the ledger takes for it at the contract's address (Received). Make
//! public 35 ₳ to an address.

use pallas_addresses::{
    Address, Network, PaymentKeyHash, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
};
use pallas_crypto::hash::{Hash, Hasher};
use pallas_crypto::key::ed25519::SecretKey;
use pallas_txbuilder::Output;
use pallas_wallet::PrivateKey;
use rand_core::OsRng;
use seedelf_core::address::wallet_contract;
use seedelf_core::assets::{Asset, Assets};
use seedelf_core::build::{self, AddressPayment, Chain, Class, Histories, Origin, Purpose};
use seedelf_core::constants::get_config;
use seedelf_core::transaction::calculate_min_required_utxo;
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{Asset as KoiosAsset, InlineDatum, ProtocolParameters, UtxoResponse};
use serde_json::{Value, json};

const TOKEN_POLICY: &str = "c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0";
/// About what a box back from Lovejoin brings: 10 ₳ less the withdraw's fee.
const BOX: u64 = 9_710_000;
const ADA: u64 = 1_000_000;

fn chain() -> Chain {
    let rows: Value = serde_json::from_str(include_str!("fixtures/epoch_params.json")).unwrap();
    Chain {
        params: ProtocolParameters::from_koios(&rows[0]).unwrap(),
        network_flag: true,
        config: get_config(1, true).unwrap(),
    }
}

struct World {
    chain: Chain,
    owner: Register,
    wallet: Address,
    signer: Hash<28>,
}

fn world() -> World {
    let chain = chain();
    let key = SecretKey::new(OsRng);
    World {
        wallet: wallet_contract(true, chain.config.contract.wallet_contract_hash),
        chain,
        owner: Register::create(random_scalar()).unwrap(),
        signer: Hasher::<224>::hash(PrivateKey::from(key).public_key().as_ref()),
    }
}

/// A wallet-contract UTxO owned by `w`, made by the transaction `[a, b; 32]`,
/// holding one of each token named in `names` (raw bytes), as Koios returns it.
fn owned(w: &World, a: u8, b: u8, lovelace: u64, names: &[Vec<u8>]) -> UtxoResponse {
    let register = w.owner.clone().rerandomize().unwrap();
    let mut hash = [a; 32];
    hash[31] = b;
    UtxoResponse {
        tx_hash: hex::encode(hash),
        tx_index: 0,
        address: w.wallet.to_bech32().unwrap(),
        value: lovelace.to_string(),
        payment_cred: hex::encode(w.chain.config.contract.wallet_contract_hash),
        inline_datum: Some(InlineDatum {
            bytes: hex::encode(register.to_vec().unwrap()),
            value: json!({
                "constructor": 0,
                "fields": [{"bytes": register.generator}, {"bytes": register.public_value}]
            }),
        }),
        asset_list: Some(
            names
                .iter()
                .map(|name| KoiosAsset {
                    decimals: 0,
                    quantity: "1".to_string(),
                    policy_id: TOKEN_POLICY.to_string(),
                    asset_name: hex::encode(name),
                    fingerprint: String::new(),
                })
                .collect(),
        ),
        ..Default::default()
    }
}

/// The least the ledger takes for one output at the contract's (enterprise)
/// address holding one of each of `names` under an inline register: what a
/// stranger pays the Seedelf at the least.
fn least_on_chain(w: &World, names: &[Vec<u8>]) -> u64 {
    let policy: [u8; 28] = hex::decode(TOKEN_POLICY).unwrap().try_into().unwrap();
    let register = w.owner.clone().rerandomize().unwrap();
    let mut output =
        Output::new(w.wallet.clone(), 5_000_000).set_inline_datum(register.to_vec().unwrap());
    for name in names {
        output = output.add_asset(Hash::new(policy), name.clone(), 1).unwrap();
    }
    calculate_min_required_utxo(output, &w.chain.params).unwrap()
}

fn class(id: &str, origin: Origin) -> Class {
    Class {
        id: id.into(),
        origin,
    }
}

fn histories(purpose: Purpose, utxos: &[(&UtxoResponse, Class)]) -> Histories {
    utxos.iter().fold(Histories::new(purpose), |h, (u, c)| {
        h.with(&u.tx_hash, u.tx_index, c.clone())
    })
}

fn pay(lovelace: u64) -> Vec<AddressPayment> {
    vec![AddressPayment {
        to: ShelleyAddress::new(
            Network::Testnet,
            ShelleyPaymentPart::Key(PaymentKeyHash::new([7; 28])),
            ShelleyDelegationPart::Null,
        )
        .into(),
        lovelace,
        tokens: Assets::new(),
    }]
}

fn outpoints(utxos: &[UtxoResponse]) -> Vec<String> {
    let mut v: Vec<String> = utxos
        .iter()
        .map(|u| format!("{}#{}", u.tx_hash, u.tx_index))
        .collect();
    v.sort();
    v
}

#[test]
fn a_payment_the_clis_order_makes_is_not_refused_for_a_bundle_that_costs_more_than_it_adds() {
    let w = world();
    let names: Vec<Vec<u8>> = (0..200u16).map(|i| vec![i as u8]).collect();
    let d_least = least_on_chain(&w, &names);

    let o1 = owned(&w, 0x01, 0, 20 * ADA, &[]);
    let b1 = owned(&w, 0xb0, 0, BOX, &[]);
    let b2 = owned(&w, 0xb0, 1, BOX, &[]);
    let d = owned(&w, 0xd0, 0, d_least, &names);
    let available = vec![o1.clone(), b1.clone(), b2.clone(), d.clone()];
    // As the extension classes them (activity.ts `classes`): money made
    // private, each box its own, a stranger's payment received.
    let h = histories(
        Purpose::Pay,
        &[
            (&o1, class("public", Origin::Own)),
            (&b1, class(&format!("box:{}", b1.tx_hash), Origin::Lovejoin)),
            (&b2, class(&format!("box:{}", b2.tx_hash), Origin::Lovejoin)),
            (&d, class(&format!("received:{}", d.tx_hash), Origin::Received)),
        ],
    );
    let payment = pay(35 * ADA);

    // D's tokens re-made as change, 20 to an output, need more than D holds.
    let d_tokens = names.iter().fold(Assets::new(), |all, n| {
        all.add(Asset::new(TOKEN_POLICY.to_string(), hex::encode(n), 1).unwrap())
            .unwrap()
    });
    let kept = build::minimum_deposit(&w.chain.params, &d_tokens).unwrap();
    println!("D holds {d_least} lovelace (its least on chain); its tokens as change need {kept}");
    assert!(kept > d_least);

    // Everything together is short ...
    let whole = build::sweep_many_from(&w.chain, &available, &payment, &w.owner, w.signer)
        .unwrap()
        .estimate();
    let e = whole.err().expect("all four together pay");
    println!("O1 + D + B1 + B2: {e} (is_short = {})", build::is_short(&e));
    assert!(build::is_short(&e), "{e}");

    // ... while O1 and the two boxes pay it, with change of ADA alone.
    let subset = vec![o1.clone(), b1.clone(), b2.clone()];
    let paid = build::sweep_many_from(&w.chain, &subset, &payment, &w.owner, w.signer)
        .unwrap()
        .estimate()
        .expect("O1 + B1 + B2 pay 35 ₳");
    println!(
        "O1 + B1 + B2: fee {} lovelace, change {} lovelace, change tokens {}",
        paid.fee.total,
        paid.change_lovelace,
        paid.change_tokens.items.len()
    );

    // The CLI's order (sweep_many: no histories) makes exactly that payment.
    let blind = build::sweep_many(&w.chain, &available, &payment, &w.owner, w.signer)
        .expect("the CLI's order pays 35 ₳");
    assert_eq!(outpoints(&blind.inputs()), outpoints(&subset));
    println!("sweep_many (the CLI's order): Ok, spends O1, B1, B2");

    // The promise (build.rs's section comment, privacy.md): keeping histories
    // apart never refuses a payment the CLI's order makes.
    let apart = build::sweep_many_apart(&w.chain, &available, &h, &payment, &w.owner, w.signer);
    match &apart {
        Ok(spend) => println!("sweep_many_apart: Ok, {} inputs", spend.inputs().len()),
        Err(e) => println!("sweep_many_apart: Err({e}), is_short = {}", build::is_short(e)),
    }
    let spent = apart
        .unwrap_or_else(|e| panic!("refused a payment the CLI's order makes: {e}"))
        .inputs();
    // O1, B1 and B2 are the only UTxOs that pay it.
    assert_eq!(outpoints(&spent), outpoints(&subset));
}

