    let params = fixture_params();
    // The CIP-30 address: A holds 50 ₳ and 1 of an unrelated token, B holds
    // 1.5 ₳ and the 100 being sent, C is a pure 5 ₳ UTxO (an assumed
    // collateral, so fund leaves it out). 51.5 ₳ and the token are usable.
    let address = vec![
        token_utxo(0x01, 50_000_000, &[(PID_OTHER, "bb", 1)]),
        token_utxo(0x02, 1_500_000, &[(PID_SENT, "aa", 100)]),
        ada_utxo(0x03, 5_000_000),
    ];
    let usable = utxos::collect_address_utxos(address).unwrap();
    assert_eq!(usable.len(), 2, "fund leaves out only the pure 5 ₳ UTxO");

    // `fund --lovelace 10000000 --asset <PID_SENT>.aa=100`
    let ten_ada: u64 = 10_000_000;
    let picked_ten = utxos::select(&params, usable.clone(), ten_ada, sent()).unwrap();
    // `fund --asset <PID_SENT>.aa=100` with no --lovelace: the token output's minimum
    let token_min: u64 = wallet_minimum_lovelace_with_assets(&params, sent()).unwrap();
    let picked_min = utxos::select(&params, usable, token_min, sent()).unwrap();

    assert!(
        !picked_ten.is_empty() && !picked_min.is_empty(),
        "the address holds 51.5 ₳ and the token, yet select picked {} UTxOs for 10 ₳ with the \
         token and {} for the token with its minimum ({token_min} lovelace): an empty pick is \
         fund's \"Not Enough Lovelace/Tokens\"",
        picked_ten.len(),
        picked_min.len(),
    );

    // What select itself promises when it picks: the token, the goal, and a
    // change output at its minimum.
    for (goal, picked) in [(ten_ada, &picked_ten), (token_min, &picked_min)] {
        let (total, found) = utxos::assets_of(picked.clone()).unwrap();
        assert!(found.contains(sent()), "the pick must hold the token sent");
        let change = found.separate(sent()).unwrap();
        let change_min = wallet_minimum_lovelace_with_assets(&params, change).unwrap();
        assert!(
            total >= goal + change_min,
            "picked {total} lovelace, short of the goal {goal} and the change's {change_min}"
        );
    }
}

//! Chunk 51, r3b#1: `orders::check_cancels` decodes the swap Minswap built
//! (bytes from outside the wallet) with `MultiEraTx::decode` and no depth
//! check of its own. Pallas decodes plutus data by recursion, so a datum a
//! few thousand levels deep overflows WebAssembly's stack and traps the
//! module (the launch review's #17, 1.6.0's 314-wasm#0). Today the wallet's
//! one caller is safe only because `cip30::inspect` runs `check_nesting` on
//! the same bytes first (sessions.ts `inspect`, then `cancelsChecked`).
//!
//! The right behaviour: the check refuses such a swap itself, before
//! decoding it, wherever the deep datum sits (in the witness set, or inline
//! in an output, inside tag 24's bytes, which Pallas decodes too), and an
//! honest swap still checks out. The deep cases run on a thread with a large
//! stack, so that natively they show what `check_cancels` returns rather than
//! overflow the test's own stack.

use pallas_addresses::{
    Address, Network, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
};
use pallas_crypto::hash::{Hash, Hasher};
use pallas_txbuilder::{BuildConway, Input, Output, StagingTransaction};
use seedelf_core::cbor::{MAX_DEPTH, within_depth};
use seedelf_core::orders::{self, Credential, Protocol, Session, SwapCheck};
use seedelf_koios::koios::{ProtocolParameters, UtxoResponse};
use serde_json::{Value, json};

/// Levels of nesting: past the few thousand that overflowed WebAssembly's
/// stack, and about 4 KB, well within a transaction's 16 KiB.
const DEEP: usize = 4_000;

fn params() -> ProtocolParameters {
    let rows: Value =
        serde_json::from_str(include_str!("fixtures/epoch_params_mainnet.json")).unwrap();
    let row = if rows.is_array() { &rows[0] } else { &rows };
    ProtocolParameters::from_koios(row).unwrap()
}

/// A Koios row from a fixture's UTxO (as orders_test.rs reads them).
fn row(u: &Value) -> UtxoResponse {
    let address = Address::from_bech32(u["address"].as_str().unwrap()).unwrap();
    let payment_cred = match &address {
        Address::Shelley(s) => hex::encode(s.payment().as_hash()),
        _ => String::new(),
    };
    serde_json::from_value(json!({
        "tx_hash": u["tx_hash"],
        "tx_index": u["tx_index"],
        "address": u["address"],
        "value": u["value"],
        "stake_address": null,
        "payment_cred": payment_cred,
        "epoch_no": 0,
        "block_height": 0,
        "block_time": 0,
        "datum_hash": u.get("datum_hash").cloned().unwrap_or(Value::Null),
        "inline_datum": u.get("inline_datum").cloned().unwrap_or(Value::Null),
        "reference_script": u.get("reference_script").cloned().unwrap_or(Value::Null),
        "asset_list": u.get("asset_list").cloned().unwrap_or(json!([])),
        "is_spent": false,
    }))
    .unwrap()
}

/// `n` levels of one-item lists around a 0: plutus data Pallas decodes one
/// call deeper a level.
fn nested(n: usize) -> Vec<u8> {
    let mut v = vec![0x81; n];
    v.push(0x00);
    v
}

/// Minswap V2's real mainnet order (tests/fixtures/order_cancels.json), its
/// owner as the session.
struct Setup {
    session: Session,
    address: Address,
    order: UtxoResponse,
    datum: Vec<u8>,
    references: Vec<UtxoResponse>,
    params: ProtocolParameters,
}

impl Setup {
    fn minswap_v2() -> Self {
        let fixtures: Vec<Value> =
            serde_json::from_str(include_str!("fixtures/order_cancels.json")).unwrap();
        let f = fixtures
            .iter()
            .find(|f| f["protocol"] == "MinswapV2" && f["network"] == "mainnet")
            .unwrap();
        let protocol: Protocol = serde_json::from_value(json!("MinswapV2")).unwrap();
        let datum = hex::decode(f["datum"].as_str().unwrap()).unwrap();
        let to = orders::read(protocol, &datum).unwrap().pays[0];
        let (Credential::Key(payment), Some(Credential::Key(stake))) = (to.payment, to.stake)
        else {
            panic!("Minswap V2's order doesn't pay a base address of keys");
        };
        let session = Session { payment, stake };
        Setup {
            session,
            address: Address::Shelley(ShelleyAddress::new(
                Network::Mainnet,
                ShelleyPaymentPart::key_hash(payment),
                ShelleyDelegationPart::key_hash(stake),
            )),
            order: row(&f["order"]),
            datum,
            references: vec![row(&f["reference"])],
            params: params(),
        }
    }

    /// A swap as Minswap builds one: the session's change at output 0, the
    /// order (its datum inline) at output 1, and, when `deep` is given, an
    /// output at the session's address under a datum nested `DEEP` levels:
    /// carried in the witness set for its hash, or inline.
    fn swap(&self, deep: Option<Deep>) -> Vec<u8> {
        let mut order = Output::new(
            Address::from_bech32(&self.order.address).unwrap(),
            self.order.value.parse().unwrap(),
        );
        for a in self.order.asset_list.iter().flatten() {
            let policy: [u8; 28] = hex::decode(&a.policy_id).unwrap().try_into().unwrap();
            order = order
                .add_asset(
                    Hash::new(policy),
                    hex::decode(&a.asset_name).unwrap(),
                    a.quantity.parse().unwrap(),
                )
                .unwrap();
        }
        let mut tx = StagingTransaction::new()
            .input(Input::new(Hash::new([0x77; 32]), 0))
            .output(Output::new(self.address.clone(), 3_000_000))
            .output(order.set_inline_datum(self.datum.clone()));
        match deep {
            None => {}
            Some(Deep::Witness) => {
                let datum = nested(DEEP);
                tx = tx
                    .output(
                        Output::new(self.address.clone(), 2_000_000)
                            .set_datum_hash(Hasher::<256>::hash(&datum)),
                    )
                    .datum(datum);
            }
            Some(Deep::Inline) => {
                tx = tx.output(
                    Output::new(self.address.clone(), 2_000_000).set_inline_datum(nested(DEEP)),
                );
            }
        }
        tx.fee(200_000).build_conway_raw().unwrap().tx_bytes.0
    }

    /// `check_cancels` on the swap's order at output 1.
    fn check(&self, tx: &[u8]) -> anyhow::Result<Vec<orders::CancelCheck>> {
        orders::check_cancels(&SwapCheck {
            params: &self.params,
            network_flag: false,
            session: self.session,
            address: &self.address,
            tx_cbor: tx,
            orders: &[1],
            references: &self.references,
        })
    }
}

#[derive(Clone, Copy, Debug)]
enum Deep {
    Witness,
    Inline,
}

#[test]
fn a_swap_nested_too_deep_is_refused_by_the_order_check_itself() {
    let run = std::thread::Builder::new()
        .stack_size(256 << 20)
        .spawn(|| {
            let s = Setup::minswap_v2();

            // The honest swap checks out: its order's cancel builds and runs.
            let honest = s.swap(None);
            assert!(within_depth(&honest, MAX_DEPTH));
            let checks = s.check(&honest).expect("an honest swap is read");
            assert_eq!(checks.len(), 1);
            assert_eq!(checks[0].why, None, "{:?}", checks[0]);
            assert!(checks[0].fee.is_some(), "{:?}", checks[0]);

            // The same swap with a datum `DEEP` levels down. Core's own walk
            // already calls the witness set's too deep (a tag-24 inline datum
            // it doesn't open; cip30's `nests_within` does).
            let mut wrong = Vec::new();
            for deep in [Deep::Witness, Deep::Inline] {
                let tx = s.swap(Some(deep));
                eprintln!(
                    "{deep:?}: {} bytes, core's within_depth(tx, {MAX_DEPTH}) = {}",
                    tx.len(),
                    within_depth(&tx, MAX_DEPTH)
                );
                match s.check(&tx) {
                    Err(e) if e.to_string().contains("nested") => {
                        eprintln!("{deep:?}: refused: {e}");
                    }
                    other => {
                        let got = format!("{other:?}");
                        eprintln!("{deep:?}: check_cancels returned {got}");
                        wrong.push(format!("{deep:?}: {got}"));
                    }
                }
            }
            assert!(
                wrong.is_empty(),
                "check_cancels decoded a swap nested {DEEP} levels deep instead of refusing it: {wrong:#?}"
            );
        })
        .unwrap();
    if let Err(panic) = run.join() {
        std::panic::resume_unwind(panic);
    }
}

// Chunk 51, r4#3 (the verifier's test). The CLI's signing page,
// seedelf-cli/static/index.js, adds the CIP-30 wallet's witnesses to the
// transaction that `create`, `fund` and `util extract` serve by searching its
// hex for the first "a105" (else the first "a0f5f6"), at any nibble, and
// splicing there. Pallas writes the witness set after the body (`84 body
// witnesses f5 f6`): `a0` when there's no redeemer (fund), `a1 05 …` when there
// is one (create, extract). A body whose hex happens to hold those digits (the
// user's address, an input's id, the fresh datum) gets the witnesses written
// into it, so the page submits a transaction whose body isn't the one the
// wallet signed, and the node refuses it.
//
// This runs the page itself, its two injected blocks filled as web_server.rs
// fills index.html's, against a fake CIP-30 wallet, and reads what it submits.

import { readFileSync } from "node:fs";
import { createContext, runInContext } from "node:vm";

import { describe, expect, it } from "vitest";

import { nestsWithin, skip, txId } from "../src/background/cbor";

const cliStatic = (file: string) =>
  readFileSync(new URL(`../../../seedelf-cli/static/${file}`, import.meta.url), "utf8");
const pageScript = cliStatic("index.js");
const pageHtml = cliStatic("index.html");

/** index.html's two injected blocks, filled as web_server.rs fills them (mainnet). */
function serve(message: string): { data: string; network: string } {
  const filled = pageHtml
    .replace('{ "message": "ACAB000000000000" }', `{ "message": ${JSON.stringify(message)} }`)
    .replace('{ "network": "FADECAFE00000000" }', '{ "network": "" }');
  const block = (id: string) => {
    const found = filled.match(new RegExp(`<script id="${id}" type="application/json">([\\s\\S]*?)</script>`));
    if (!found) throw new Error(`index.html has no ${id} block`);
    return found[1]!;
  };
  return { data: block("injected-data"), network: block("injected-network-data") };
}

interface FakeElement {
  textContent: string;
  href: string;
  value: string;
  children: unknown[];
  appendChild(child: unknown): void;
}

const element = (text = ""): FakeElement => ({
  textContent: text,
  href: "",
  value: "",
  children: [],
  appendChild(child) {
    this.children.push(child);
  },
});

// What the CIP-30 wallet's signTx returns: a witness set of one vkey witness, in a tagged set.
const VKEY = "cfa04a87c36a5e1cd5265e8b5561dbc3f24181e92a8ebf4d39c67277a6b21941";
const SIGNATURE =
  "fa09919d49f8338b0feedd4741cdc79f20a340ffe4f55c6e9322675bcc1a3dcf13a1c212fad4b95ba04a5fde0be7dd1868557f0c8c807b8d6f356017fd5c8bc3";
const VKEYS = `d9010281825820${VKEY}5840${SIGNATURE}`;
const WALLET_WITNESSES = `a100${VKEYS}`;

/** Runs the page on `unsigned`, with the wallet picked in the dropdown; returns what it signed and submitted. */
async function signOnThePage(unsigned: string): Promise<{ signed?: string; submitted?: string; status: string }> {
  const served = serve(unsigned);
  const elements: Record<string, FakeElement> = {
    "injected-data": element(served.data),
    "injected-network-data": element(served.network),
    status: element(),
    tx_link: element(),
    tx_cbor: element(),
    wallet_dropdown: element(),
  };
  elements.wallet_dropdown!.value = "cliwallet";
  const seen: { signed?: string; submitted?: string; onLoad?: () => Promise<void> } = {};
  const api = {
    getNetworkId: async () => 1,
    signTx: async (tx: string) => {
      seen.signed = tx;
      return WALLET_WITNESSES;
    },
    submitTx: async (tx: string) => {
      seen.submitted = tx;
      return "ab".repeat(32);
    },
  };
  const cardano = {
    cliwallet: { name: "cliwallet", icon: "data:,", apiVersion: "0.1.0", isEnabled: async () => true, enable: async () => api },
  };
  const document = {
    getElementById: (id: string) => elements[id],
    createElement: () => element(),
    addEventListener: (type: string, listener: () => Promise<void>) => {
      if (type === "DOMContentLoaded") seen.onLoad = listener;
    },
  };
  runInContext(pageScript, createContext({ window: { cardano }, document, setInterval, clearInterval }), {
    filename: "seedelf-cli/static/index.js",
  });
  if (!seen.onLoad) throw new Error("index.js didn't wait for DOMContentLoaded");
  await seen.onLoad();
  return { signed: seen.signed, submitted: seen.submitted, status: elements.status!.textContent };
}

const bytes = (hex: string) => Uint8Array.from(hex.match(/../g) ?? [], (h) => Number.parseInt(h, 16));

/** A transaction's id, body, witness-set entries (key → value) and what follows them; or that it can't be read. */
function read(hex: string) {
  try {
    const b = bytes(hex);
    if (!/^(?:[0-9a-f]{2})+$/.test(hex) || b[0] !== 0x84 || !nestsWithin(b)) return { readable: false };
    const bodyEnd = skip(b, 1, 1);
    const head = b[bodyEnd]!;
    if (head >> 5 !== 5 || (head & 0x1f) >= 24) return { readable: false };
    const witnesses: Record<number, string> = {};
    let at = bodyEnd + 1;
    for (let i = 0; i < (head & 0x1f); i++) {
      const end = skip(b, at + 1, 2);
      witnesses[b[at]!] = hex.slice((at + 1) * 2, end * 2);
      at = end;
    }
    return { readable: true, id: txId(b), body: hex.slice(2, bodyEnd * 2), witnesses, after: hex.slice(at * 2) };
  } catch {
    return { readable: false };
  }
}

/** A CBOR unsigned integer, as minicbor writes it (under 2^32). */
const uint = (n: number) =>
  n < 24
    ? n.toString(16).padStart(2, "0")
    : n < 0x100
      ? `18${n.toString(16).padStart(2, "0")}`
      : n < 0x10000
        ? `19${n.toString(16).padStart(4, "0")}`
        : `1a${n.toString(16).padStart(8, "0")}`;
/** Writes `patch` over `hex` at byte `offset`, keeping its length. */
const put = (hex: string, offset: number, patch: string) =>
  hex.slice(0, offset * 2) + patch + hex.slice(offset * 2 + patch.length);
const input = (id: string, index: number) => `825820${id}${uint(index)}`;

// Variant 1's wallet contract and mainnet reference UTxO (seedelf-core/src/constants.rs).
const WALLET_HASH = "94bca9c099e84ffd90d150316bb44c31a78702239076a0a80ea4a469";
const WALLET_REFERENCE = "51f12c1a5c2b0558a284628d81b06dee50b27693242fe35618c5f921730c0527";
// The user's base address (payment key, stake key).
const PAY = "de863692790053e4c055b4a9b644d49611ed14dc8235790013a7f58e";
const STAKE = "1ec705de1f103925058580ef47cdabdc34315668df7f578aa2b94e8c";
// A re-randomized register: two compressed G1 points.
const GENERATOR =
  "b3cad0448fe43cf8d611d4d9522d22fdff15f53c48f6d1f3bd9fec92a4c09430256f70ae610ab15b40bef4971765dbb1";
const PUBLIC_VALUE =
  "999f8e374b862cfe9e5a91b64a788733ca794a94b45686c79d539bf3bbee469f0587d6e41c1bbbeec8352ce72ef16ec8";
const INPUT_ID = "6ca9a20adc308a22b91b77e32efa39747d5bd85929857a353f753ded8fe2f228";
const CONTRACT_UTXO = "226196b1f48f717bd6c649449260fe647c03cc37ee840550809699fe9438f176";
const USER_UTXO = "6f203ecd5078ad49c56523204326bb2c4669a420f031d7f60ecacd0974b59859";
const COLLATERAL_UTXO = "ba5ed1601d1154e027a65dc119ff78741a242f8aac30e2cb7e40f66e9250f425";
const SCRIPT_DATA_HASH = "1a87fa5a2ae1103555645f0777bd74f29cb8bc8ba02d1ada0bd81bdf1c2b09f1";
// extract's one spend redeemer, as Pallas lists it: [spend, input 0, Constr 0 [#, #, #], [mem, steps]].
const REDEEMERS = `81840000d8799f404040ff82${uint(1_052_916)}${uint(301_877_342)}`;

/**
 * `fund -a <address> -s <seedelf> -l 50000000`, as fund.rs builds it: one input,
 * 50 ₳ to the contract under a fresh register, the change back to the address,
 * the fee; no redeemer, so the witness set is empty (`a0`).
 */
function fundTx({ pay = PAY, inputId = INPUT_ID, publicValue = PUBLIC_VALUE } = {}) {
  const datum = `d8799f5830${GENERATOR}5830${publicValue}ff`;
  const toSeedelf = `a300581d71${WALLET_HASH}01${uint(50_000_000)}028201d8185868${datum}`;
  const change = `a2005839${`01${pay}${STAKE}`}01${uint(147_302_511)}`;
  const body = `a300d9010281${input(inputId, 0)}0182${toSeedelf}${change}02${uint(170_605)}`;
  return { unsigned: `84${body}a0f5f6`, body, ours: {} as Record<number, string> };
}

/**
 * `util extract -u <utxo> -a <address>`, as extract.rs builds it: the contract
 * UTxO and one of the address's, everything to the address, collateral and its
 * return, the wallet contract by reference; one spend redeemer (`a1 05 …`).
 */
function extractTx({ pay = PAY } = {}) {
  const to = `5839${`01${pay}${STAKE}`}`;
  const body =
    "a7" +
    `00d9010282${input(CONTRACT_UTXO, 0)}${input(USER_UTXO, 1)}` +
    `0181a200${to}01${uint(9_412_337)}` +
    `02${uint(287_442)}` +
    `0b5820${SCRIPT_DATA_HASH}` +
    `0dd9010281${input(COLLATERAL_UTXO, 0)}` +
    `10a200${to}01${uint(4_568_837)}` +
    `12d9010281${input(WALLET_REFERENCE, 1)}`;
  return { unsigned: `84${body}a105${REDEEMERS}f5f6`, body, ours: { 5: REDEEMERS } as Record<number, string> };
}

/** The page should submit the transaction the CLI built and the wallet signed, with the wallet's witnesses added. */
async function expectSignedAsBuilt(tx: { unsigned: string; body: string; ours: Record<number, string> }) {
  // The fixture is one whole transaction, its body ending where the witness set starts.
  expect(read(tx.unsigned)).toEqual({
    readable: true,
    id: txId(bytes(tx.unsigned)),
    body: tx.body,
    witnesses: tx.ours,
    after: "f5f6",
  });
  const run = await signOnThePage(tx.unsigned);
  expect(run.signed, run.status).toBe(tx.unsigned);
  expect(run.submitted, run.status).toBeDefined();
  expect(read(run.submitted!), `submitted ${run.submitted}`).toEqual({
    readable: true,
    id: txId(bytes(tx.unsigned)), // the body the wallet signed
    body: tx.body,
    witnesses: { 0: VKEYS, ...tx.ours },
    after: "f5f6",
  });
}

describe("the CLI's signing page adds the wallet's witnesses to the transaction it serves", () => {
  it("does, for a fund and an extract whose bytes hold neither pattern (the page works)", async () => {
    const fund = fundTx();
    const extract = extractTx();
    expect(fund.unsigned).not.toContain("a105");
    expect(fund.unsigned.indexOf("a0f5f6")).toBe(fund.unsigned.length - 6);
    expect(extract.unsigned.indexOf("a105")).toBe(2 + extract.body.length);
    await expectSignedAsBuilt(fund);
    await expectSignedAsBuilt(extract);
  });

  it("does for a fund from an address whose payment hash holds the bytes a1 05", async () => {
    const fund = fundTx({ pay: put(PAY, 14, "a105") });
    expect(fund.body).toContain(`5839${`01${put(PAY, 14, "a105")}${STAKE}`}`);
    await expectSignedAsBuilt(fund);
  });

  it("does for a fund spending an input whose id holds the bytes 0a 10 5f (a105 at an odd nibble)", async () => {
    const fund = fundTx({ inputId: put(INPUT_ID, 16, "0a105f") });
    expect(fund.body.indexOf("a105") % 2).toBe(1);
    await expectSignedAsBuilt(fund);
  });

  it("does for a fund whose fresh datum holds the bytes a0 f5 f6", async () => {
    const fund = fundTx({ publicValue: put(PUBLIC_VALUE, 20, "a0f5f6") });
    expect(fund.unsigned).not.toContain("a105");
    await expectSignedAsBuilt(fund);
  });

  it("does for an extract to an address whose payment hash holds the bytes a1 05", async () => {
    await expectSignedAsBuilt(extractTx({ pay: put(PAY, 14, "a105") }));
  });
});

//! Chunk 51, finding r4#5: the signing page has no tie to the run that served it.
//!
//! The case shown here: an earlier `fund`, to Seedelf A, still serves its
//! signing page at 127.0.0.1:44203 (left running in another terminal). A
//! second `fund`, to Seedelf B, the one the user meant, prints "Starting Web
//! Server At: http://127.0.0.1:44203/" (fund.rs:288, display.rs:9-13) before
//! anything binds, and then warp's `bind_with_graceful_shutdown` panics on the
//! taken port (web_server.rs:97-100). The page at the URL it just announced is
//! the earlier run's: it embeds, and has the browser wallet sign, the earlier
//! transaction, which pays Seedelf A.
//!
//! The right behaviour: a run never announces a signing page that holds a
//! transaction other than its own. Binding before printing the URL, and saying
//! so when the port is taken, is one way to get it.
//!
//! The earlier run serves, for real, from a thread of this test; the second run
//! is a child process (this binary, re-run on its child test alone) so that its
//! output can be read. Both read a mock Koios (tests/cli/harness.rs): no network.

#[path = "cli/harness.rs"]
mod harness;

use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use blstrs::Scalar;
use harness::*;
use pallas_traverse::MultiEraTx;
use seedelf_cli::commands::fund::{FundArgs, run};

const CHILD: &str = "R51_R4_5_CHILD";
const HOST: &str = "127.0.0.1:44203";
const URL_PREFIX: &str = "http://127.0.0.1:44203";
/// The Seedelf the user picked first, then saw was the wrong contact.
const SEEDELF_A: &str = SAMPLE_SEEDELF;
/// 100 ADA in both runs, as in the finding.
const LOVELACE: u64 = 100_000_000;

/// The Seedelf the user meant.
fn seedelf_b() -> String {
    format!("5eed0e1f{}bb", "00".repeat(27))
}

/// Fixed owners, so the parent and the child mount the same chain.
fn owner_a() -> Scalar {
    Scalar::from(0xA11CE_u64)
}

fn owner_b() -> Scalar {
    Scalar::from(0xB0B_u64)
}

/// The chain both runs read: Seedelfs A and B at the wallet contract, each
/// under its own owner's register, and the payer's 200 ADA.
async fn mount_chain(scenario: &mut Scenario) {
    scenario
        .mount_credential_utxos(vec![
            seedelf_utxo(owner_a(), 1, 1_500_000, SEEDELF_A),
            seedelf_utxo(owner_b(), 2, 1_500_000, &seedelf_b()),
        ])
        .await;
    scenario
        .mount_address_utxos(vec![address_utxo(
            &external_address_bech32(),
            3,
            200_000_000,
            &[],
        )])
        .await;
}

fn fund_args(seedelf: &str) -> FundArgs {
    FundArgs {
        address: external_address_bech32(),
        seedelf: seedelf.to_string(),
        lovelace: Some(LOVELACE),
        assets: vec![],
    }
}

/// The second run, as the parent's child process: `fund` to Seedelf B, for
/// real (the capture seam isn't armed), while the earlier run holds the port.
#[tokio::test]
async fn r51_r4_5_child_second_run() {
    if std::env::var_os(CHILD).is_none() {
        return; // only the parent's child process runs it
    }
    let mut scenario = Scenario::start().await;
    mount_chain(&mut scenario).await;
    let outcome = tokio::time::timeout(
        Duration::from_secs(60),
        run(fund_args(&seedelf_b()), PREPROD, VARIANT),
    )
    .await;
    match outcome {
        Ok(Ok(())) => println!("R51-OUTCOME: ok"),
        Ok(Err(e)) => println!("R51-OUTCOME: error: {e:#}"),
        Err(_) => println!("R51-OUTCOME: still serving after 60 s"),
    }
}

#[test]
fn r51_r4_5_a_second_run_never_announces_an_earlier_runs_page() {
    if std::env::var_os(CHILD).is_some() {
        return;
    }
    // A precondition, not the finding: the port is free for the earlier run.
    drop(TcpListener::bind(HOST).unwrap_or_else(|e| {
        panic!("precondition: {HOST} must be free for the earlier run to serve: {e}")
    }));

    // The earlier run: `fund` to Seedelf A, serving its signing page for real.
    std::thread::spawn(|| {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("runtime");
        runtime.block_on(async {
            let mut scenario = Scenario::start().await;
            mount_chain(&mut scenario).await;
            let _ = run(fund_args(SEEDELF_A), PREPROD, VARIANT).await;
        });
    });
    let earlier_tx = wait_for_tx_at("/", Duration::from_secs(120))
        .expect("precondition: the earlier run never served its page");

    // The second run, in a child process, while the earlier one still serves.
    let (stdout, stderr) = run_child(Duration::from_secs(180));
    let second_tx = line_after(&stdout, "Tx Cbor: ").unwrap_or_else(|| {
        panic!(
            "precondition: the second run never built its transaction\n\
             --- its stdout ---\n{stdout}\n--- its stderr ---\n{stderr}"
        )
    });
    assert_ne!(second_tx, earlier_tx, "two runs, two transactions");

    let announced = announced_path(&stdout);
    let served = announced.as_deref().and_then(|p| fetch_tx(p).ok().flatten());
    let panic = stderr
        .lines()
        .skip_while(|l| !l.contains("panicked"))
        .take(2)
        .collect::<Vec<_>>()
        .join(" / ");
    let outcome = line_after(&stdout, "R51-OUTCOME: ")
        .unwrap_or_else(|| "none: it never returned".to_string());

    let evidence = format!(
        "earlier run (fund -s A):  {}\n\
         second run (fund -s B):   {}\n\
         second run announced:     {}\n\
         page served there:        {}\n\
         second run's panic:       {}\n\
         second run's outcome:     {outcome}",
        describe(&earlier_tx),
        describe(&second_tx),
        announced
            .as_deref()
            .map(|p| format!("{URL_PREFIX}{p}"))
            .unwrap_or_else(|| "no URL".to_string()),
        served
            .as_deref()
            .map(describe)
            .unwrap_or_else(|| "no transaction".to_string()),
        if panic.is_empty() { "none" } else { panic.as_str() },
    );
    println!("{evidence}");

    let elsewhere = matches!(&served, Some(tx) if *tx != second_tx);
    assert!(
        !elsewhere,
        "the second fund announced a signing page that holds another run's \
         transaction: signing there pays Seedelf A, not B.\n{evidence}"
    );
}

/// Run `r51_r4_5_child_second_run` in a child process; its stdout and stderr,
/// ANSI colours stripped.
fn run_child(within: Duration) -> (String, String) {
    let mut child = Command::new(std::env::current_exe().expect("test binary"))
        .args([
            "--exact",
            "r51_r4_5_child_second_run",
            "--nocapture",
            "--test-threads=1",
        ])
        .env(CHILD, "1")
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("start the second run");
    let mut out = child.stdout.take().expect("stdout");
    let mut err = child.stderr.take().expect("stderr");
    let out_reader = std::thread::spawn(move || {
        let mut s = String::new();
        let _ = out.read_to_string(&mut s);
        s
    });
    let err_reader = std::thread::spawn(move || {
        let mut s = String::new();
        let _ = err.read_to_string(&mut s);
        s
    });
    let deadline = Instant::now() + within;
    loop {
        if child.try_wait().expect("wait for the second run").is_some() {
            break;
        }
        if Instant::now() >= deadline {
            let _ = child.kill();
            let _ = child.wait();
            break;
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    (
        strip_ansi(&out_reader.join().expect("stdout reader")),
        strip_ansi(&err_reader.join().expect("stderr reader")),
    )
}

/// GET `path` from the signing port: the transaction its page embeds, if any.
fn fetch_tx(path: &str) -> std::io::Result<Option<String>> {
    let mut stream = TcpStream::connect(HOST)?;
    stream.set_read_timeout(Some(Duration::from_secs(10)))?;
    write!(
        stream,
        "GET {path} HTTP/1.1\r\nHost: {HOST}\r\nConnection: close\r\n\r\n"
    )?;
    let mut response = String::new();
    stream.read_to_string(&mut response)?;
    const KEY: &str = r#"{ "message": ""#;
    Ok(response.find(KEY).map(|i| {
        let rest = &response[i + KEY.len()..];
        rest[..rest.find('"').unwrap_or(rest.len())].to_string()
    }))
}

fn wait_for_tx_at(path: &str, within: Duration) -> Option<String> {
    let deadline = Instant::now() + within;
    while Instant::now() < deadline {
        if let Ok(Some(tx)) = fetch_tx(path) {
            return Some(tx);
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    None
}

/// The path of the signing URL a run announced: a line holding the bare URL,
/// as `display::webserver_address` prints it.
fn announced_path(stdout: &str) -> Option<String> {
    stdout.lines().map(str::trim).find_map(|line| {
        let path = line.strip_prefix(URL_PREFIX)?;
        if path.contains(char::is_whitespace) {
            return None;
        }
        Some(if path.is_empty() { "/".to_string() } else { path.to_string() })
    })
}

fn line_after(text: &str, prefix: &str) -> Option<String> {
    text.lines()
        .map(str::trim)
        .find_map(|l| l.strip_prefix(prefix).map(|rest| rest.trim().to_string()))
}

/// A transaction's id and what it pays the wallet contract, and to whom.
fn describe(cbor: &str) -> String {
    let id = hex::decode(cbor)
        .ok()
        .and_then(|bytes| MultiEraTx::decode(&bytes).ok().map(|tx| tx.hash().to_string()))
        .unwrap_or_else(|| "undecodable".to_string());
    let paid = decode_tx(cbor)
        .outputs_to(&wallet_address())
        .iter()
        .map(|o| {
            let owner = match &o.register {
                Some(r) if r.is_owned(owner_a()).unwrap_or(false) => "Seedelf A's owner",
                Some(r) if r.is_owned(owner_b()).unwrap_or(false) => "Seedelf B's owner",
                _ => "neither owner",
            };
            format!(
                "{} lovelace to {} for {owner}",
                o.lovelace,
                o.address.to_bech32().unwrap_or_default()
            )
        })
        .collect::<Vec<_>>()
        .join("; ");
    format!("tx {id}, {paid}")
}

fn strip_ansi(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '\u{1b}' {
            out.push(c);
            continue;
        }
        if chars.peek() == Some(&'[') {
            chars.next();
            for n in chars.by_ref() {
                if n.is_ascii_alphabetic() {
                    break;
                }
            }
        }
    }
    out
}

//! Chunk 51, finding r4#6: the CLI's signing server answers any Host header,
//! so a DNS-rebinding page can read the unsigned transaction.
//!
//! Once a site has rebound its own name to 127.0.0.1, the browser sends the
//! site's requests for http://<that name>:44203/ to the CLI's server, with
//! `Host: <that name>:44203`, and the site reads the answers as its own
//! origin's. The right behaviour: the server answers only its own authority,
//! the one it prints (127.0.0.1:44203, or localhost:44203), and a request for
//! any other Host gets neither a 2xx nor the transaction.
//!
//! This drives the real `fund` command against tests/cli's mock Koios (its
//! harness is included here unchanged) with the capture seam left unarmed, so
//! `seedelf_cli::web_server::run_web_server` really serves on 127.0.0.1:44203.
//! The request with the server's own Host is the control: it must get the
//! page and this run's fund transaction, before a fix and after it.

#[path = "cli/harness.rs"]
mod harness;

use std::time::Duration;

use harness::*;
use seedelf_cli::commands::fund::{FundArgs, run};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio::time::{Instant, sleep, timeout};

/// Where the CLI serves its signing page, as `display::webserver_address` prints it.
const SERVER: &str = "127.0.0.1:44203";
/// The Host a browser sends for a site whose name now resolves to 127.0.0.1.
const REBOUND_HOST: &str = "rebind.example:44203";

/// One `GET /` to the signing server with the given Host header: the status
/// code and the whole raw response, head and body.
async fn get_page(host: &str) -> std::io::Result<(u16, String)> {
    let mut stream = TcpStream::connect(SERVER).await?;
    let request =
        format!("GET / HTTP/1.1\r\nHost: {host}\r\nAccept: text/html\r\nConnection: close\r\n\r\n");
    stream.write_all(request.as_bytes()).await?;
    let mut raw = Vec::new();
    timeout(Duration::from_secs(10), stream.read_to_end(&mut raw))
        .await
        .map_err(|_| std::io::Error::new(std::io::ErrorKind::TimedOut, "no answer in 10 s"))??;
    let text = String::from_utf8_lossy(&raw).into_owned();
    let status = text
        .split_whitespace()
        .nth(1)
        .and_then(|code| code.parse().ok())
        .unwrap_or(0);
    Ok((status, text))
}

/// The transaction hex the page carries in its `injected-data` block.
fn injected_tx(page: &str) -> Option<String> {
    const OPEN: &str = r#"{ "message": ""#;
    let start = page.find(OPEN)? + OPEN.len();
    let len = page[start..].find('"')?;
    Some(page[start..start + len].to_string())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn signing_server_gives_the_transaction_only_to_its_own_host() {
    // The port is fixed: with anything else listening there, this test
    // couldn't tell the CLI's server from it.
    drop(std::net::TcpListener::bind(SERVER).unwrap_or_else(|err| {
        panic!("{SERVER} is in use ({err}): stop whatever listens there and run again")
    }));

    let mut scenario = Scenario::start().await;
    scenario
        .mount_credential_utxos(vec![seedelf_utxo(
            scenario.scalar,
            1,
            1_500_000,
            SAMPLE_SEEDELF,
        )])
        .await;
    scenario
        .mount_address_utxos(vec![address_utxo(
            &external_address_bech32(),
            2,
            10_000_000,
            &[],
        )])
        .await;
    // The capture seam stays unarmed: fund ends in the real signing server,
    // which serves until Ctrl-C. Dropping the future below stops it.

    let fund = run(
        FundArgs {
            address: external_address_bech32(),
            seedelf: SAMPLE_SEEDELF.to_string(),
            lovelace: Some(3_000_000),
            assets: vec![],
        },
        PREPROD,
        VARIANT,
    );

    let probe = async {
        let deadline = Instant::now() + Duration::from_secs(60);
        let own = loop {
            match get_page(SERVER).await {
                Ok(answer) => break answer,
                Err(err) if Instant::now() >= deadline => {
                    panic!("the signing server never answered on {SERVER}: {err}")
                }
                Err(_) => sleep(Duration::from_millis(50)).await,
            }
        };
        // A connection the server drops or resets hands the site nothing.
        let rebound = get_page(REBOUND_HOST).await.unwrap_or((0, String::new()));
        (own, rebound)
    };

    let ((own_status, own_page), (status, page)) = tokio::select! {
        ended = fund => panic!("fund stopped before its page was read: {ended:?}"),
        answers = probe => answers,
    };

    // The control: the page the CLI prints works, with this run's transaction.
    assert_eq!(own_status, 200, "the signing page at {SERVER} must load:\n{own_page}");
    let tx_hex = injected_tx(&own_page).expect("the signing page carries the transaction");
    let tx = decode_tx(&tx_hex);
    let funded: Vec<u64> = tx
        .outputs_to(&wallet_address())
        .iter()
        .map(|o| o.lovelace)
        .collect();
    assert_eq!(funded, vec![3_000_000], "the page carries this run's fund transaction");

    // The finding: a request for any other Host gets neither a 2xx nor the
    // transaction.
    let leaked = page.contains(&tx_hex);
    let what = if leaked {
        let outputs: Vec<String> = tx
            .outputs
            .iter()
            .map(|o| {
                format!(
                    "{} lovelace to {}{}",
                    o.lovelace,
                    o.address.to_bech32().unwrap_or_default(),
                    if o.has_datum { " (with a datum)" } else { "" }
                )
            })
            .collect();
        format!(
            "and the unsigned transaction ({} hex chars): it spends {:?}, pays {}",
            tx_hex.len(),
            tx.inputs,
            outputs.join(", and ")
        )
    } else {
        "and no transaction".to_string()
    };
    assert!(
        !(200..300).contains(&status) && !leaked,
        "a request with Host: {REBOUND_HOST}, a DNS-rebinding site's own origin, got status {status} {what}"
    );
}

//! Chunk 51, finding r4#7: `util extract` must rescue a datum-less UTxO at the
//! wallet contract's staked form (its script hash with the [LOGIC] stake key),
//! where every CLI up to 0.4.10 paid the contract. The deployed contract
//! (5b82530, `validators/wallet.ak`) lets anyone spend a UTxO with no datum
//! (`None -> True`) and never reads the delegation part, so the address's
//! payment credential is what makes a UTxO the contract's.
//!
//! Drives the real `util extract` run against the CLI's offline mock Koios,
//! reusing `tests/cli/harness.rs` as is.

#[path = "cli/harness.rs"]
mod harness;

use pallas_addresses::{
    Address, Network, ScriptHash, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
    StakeAddress, StakeKeyHash,
};
use serial_test::serial;

use seedelf_cli::commands::util::extract::{ExtractArgs, run};
use seedelf_core::constants::PREPROD_STAKE_HASH;

use harness::*;

/// The contract's staked form on preprod: what `address::wallet_contract`
/// returned before 2c67e94c (0.5.0).
fn staked_wallet_contract() -> ShelleyAddress {
    ShelleyAddress::new(
        Network::Testnet,
        ShelleyPaymentPart::Script(ScriptHash::new(config().contract.wallet_contract_hash)),
        ShelleyDelegationPart::Key(StakeKeyHash::new(PREPROD_STAKE_HASH)),
    )
}

#[tokio::test]
#[serial]
async fn extract_rescues_a_datum_less_utxo_at_the_contracts_staked_form() {
    let staked = staked_wallet_contract();
    let Address::Shelley(enterprise) = wallet_address() else {
        panic!("the wallet contract is a Shelley address");
    };
    // The same script: only the delegation part differs.
    assert_eq!(staked.payment(), enterprise.payment());
    assert_ne!(Address::from(staked.clone()), wallet_address());

    // As Koios's utxo_info lists it: the full bech32, the stake address apart.
    let mut extracted = empty_datum_utxo(50, 2_000_000, &[]);
    extracted.address = staked.to_bech32().expect("staked bech32");
    extracted.stake_address = Some(
        StakeAddress::try_from(staked.clone())
            .expect("stake address")
            .to_bech32()
            .expect("stake bech32"),
    );

    let mut scenario = Scenario::start().await;
    scenario.mount_utxo_info(vec![extracted]).await;
    scenario
        .mount_address_utxos(vec![
            // a clean 5 ADA UTxO the command picks up as collateral
            address_utxo(&external_address_bech32(), 51, 5_000_000, &[]),
            address_utxo(&external_address_bech32(), 52, 10_000_000, &[]),
        ])
        .await;
    scenario.mount_evaluate(1).await;
    scenario.arm_web_capture();

    run(
        ExtractArgs {
            utxo: format!("{}#0", tx_hash(50)),
            address: external_address_bech32(),
        },
        PREPROD,
        VARIANT,
    )
    .await
    .expect("a datum-less UTxO at the contract's staked form is the contract's: extract should rescue it");

    let params = protocol_params().await;
    let tx = decode_tx(&scenario.captured_cbor());
    assert_sound_transaction(&tx, &scenario, &params);

    // The staked-form UTxO plus the funding UTxO are spent into one output.
    let mut inputs = tx.inputs.clone();
    inputs.sort();
    assert_eq!(inputs, vec![(tx_hash(50), 0), (tx_hash(52), 0)]);
    assert_eq!(tx.outputs.len(), 1);
    assert_eq!(tx.outputs_to(&external_address()).len(), 1);
    assert_eq!(tx.collateral, vec![(tx_hash(51), 0)]);
}

