//! Chunk 51, finding r4#8: `util mint -g -p` writes the register it's given
//! as the new Seedelf's datum unchanged (`commands/util/mint.rs:76-83`, then
//! `seedelf-core`'s `mint_from`, whose `set_inline_datum(seedelf.to_vec())`
//! uses it as given). The README's `util mint` row has the minter use the
//! recipient's `util base` register, `(G1, G1^x)`, so two people minting a
//! Seedelf for the same recipient put one datum on chain twice, and anyone
//! scanning the contract sees both Seedelfs are one person's. `create` and
//! `util mint` without the flags write a fresh re-randomization each time.
//!
//! The right behaviour: a Seedelf minted for someone else sits under a fresh
//! re-randomization of the register given, still theirs (one scalar on both
//! points), so no two mints share a datum and none is the base register.
//!
//! Drives the real `util mint` run twice, with two different minters, against
//! the CLI's offline mock Koios, reusing `tests/cli/harness.rs` as is.

#[path = "cli/harness.rs"]
mod harness;

use blstrs::Scalar;
use serial_test::serial;

use seedelf_cli::commands::util::mint::{MintArgs, run};
use seedelf_core::build::is_payable;
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;

use harness::*;

/// A fresh minter (each `Scenario` has its own wallet scalar) mints a Seedelf
/// for the holder of `recipient`, given as `-g` and `-p`, from one owned UTxO
/// `n`. Returns the minted Seedelf's datum, after checking the transaction
/// conserves value, keeps every output above its minimum, and gives the
/// change back to the minter. The scenario drops here, before the next starts.
async fn mint_for(recipient: &Register, label: &str, n: u64) -> Register {
    let mut scenario = Scenario::start().await;
    scenario
        .mount_credential_utxos(vec![wallet_utxo(scenario.scalar, n, 10_000_000, &[])])
        .await;
    scenario.mount_evaluate_mint(1).await;
    scenario.mount_collateral().await;
    scenario.mount_submit().await;

    run(
        MintArgs {
            label: Some(label.to_string()),
            generator: Some(recipient.generator.clone()),
            public_value: Some(recipient.public_value.clone()),
            utxos: None,
        },
        PREPROD,
        VARIANT,
    )
    .await
    .expect("util mint -g -p should succeed");

    let params = protocol_params().await;
    let tx = decode_tx(&scenario.submitted_cbor().await);
    assert_value_conserved(&tx, &scenario.ledger);
    assert_no_sub_min_outputs(&tx, &params);

    let policy = seedelf_policy();
    let minted: i128 = tx
        .mint
        .iter()
        .filter(|((p, _), _)| p == &policy)
        .map(|(_, qty)| *qty)
        .sum();
    assert_eq!(minted, 1, "exactly one Seedelf token is minted");

    let wallet = wallet_address();
    let (seedelfs, change): (Vec<&DecodedOutput>, Vec<&DecodedOutput>) = tx
        .outputs_to(&wallet)
        .into_iter()
        .partition(|o| o.assets.keys().any(|(p, _)| p == &policy));
    assert_eq!(seedelfs.len(), 1, "one output holds the new Seedelf");
    assert_eq!(change.len(), 1, "one change output");
    let back = change[0].register.as_ref().expect("the change carries a Register");
    assert!(
        back.is_owned(scenario.scalar).expect("change ownership"),
        "the change goes back to the minter"
    );
    seedelfs[0]
        .register
        .clone()
        .expect("the Seedelf output carries a Register datum")
}

#[tokio::test]
#[serial]
async fn util_mint_for_someone_else_rerandomizes_the_register_given() {
    // Alice's key, and what `util base` prints for her: `Register::create`.
    let alice: Scalar = random_scalar();
    let base = Register::create(alice).expect("Alice's base register");
    let g1 = Register::create(Scalar::from(1u64))
        .expect("G1")
        .generator;
    assert_eq!(base.generator, g1, "util base's generator is G1 itself");

    // Bob mints her a Seedelf from the register she gave him, then Carol does.
    let from_bob = mint_for(&base, "for alice", 1).await;
    let from_carol = mint_for(&base, "for alice too", 2).await;

    // Holds today and after a fix: each is Alice's, and safe to pay.
    for (minter, datum) in [("Bob", &from_bob), ("Carol", &from_carol)] {
        assert!(
            datum.is_owned(alice).expect("ownership"),
            "{minter}'s mint must sit under a register Alice's key owns"
        );
        assert!(is_payable(datum), "{minter}'s mint must sit under a payable register");
    }

    // The bug: each Seedelf's datum is Alice's base register, byte for byte.
    assert_ne!(
        from_bob, base,
        "Bob's mint put Alice's base register on chain as given, not re-randomized"
    );
    assert_ne!(
        from_carol, base,
        "Carol's mint put Alice's base register on chain as given, not re-randomized"
    );
    assert_ne!(
        from_bob.generator, g1,
        "a Seedelf minted for someone else is marked by G1 as its generator"
    );
    assert_ne!(
        from_bob, from_carol,
        "two Seedelfs minted for Alice share one datum: anyone can see they're one person's"
    );
}

//! Chunk 51, w1a#1: Max in parts (`build_transfer_parts`, a single payment with `lovelace` null) goes straight to
//! `max_in_parts`, which never checks that the tokens it's asked to send are in the UTxOs it's given. The Send
//! form offers a token's whole held figure (`unlocked(balances.seedelf)`), which counts UTxOs a chain being sent
//! has reserved; `readContract` leaves those out of `utxos`. Asked for more of a token than `utxos` hold, a part
//! with no holder left picks nothing and `fit_part` bails with a plain "Not enough ADA" (not core's `NotEnough`),
//! which `max_in_parts` reads as a part that failed for its tokens: the UTxOs of ADA alone stay, blamed on a token
//! (`LeftWhy::Tokens`), or, with none of the token there, Max is refused as short of ADA. One transaction's Max
//! refuses both in words through core's `holding`.
//!
//! The right behaviour, whichever fix the owner picks: refused in words naming the token, as one transaction's
//! Max is, or built so that every UTxO of ADA alone goes (Max leaves nothing it could spend).

use seedelf_core::assets::{Asset, Assets};
use seedelf_core::transaction::wallet_minimum_lovelace_with_assets;
use seedelf_crypto::derivation::seedelf_key_v1;
use seedelf_koios::koios::{Asset as Held, ProtocolParameters, UtxoResponse};
use seedelf_wasm::api::{self, SeedelfPayment, TokenAmount, TransferRequest};
use serde_json::Value;

const PHRASE: &str = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

fn fixture(path: &str) -> Value {
    let path = format!("{}/{path}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn params() -> Value {
    fixture("../../seedelf-core/tests/fixtures/epoch_params.json")[0].clone()
}

/// The phrase's 25 ADA contract UTxO: every UTxO here is a copy of it, its own outpoint.
fn base() -> UtxoResponse {
    serde_json::from_value(
        fixture("../extension/tests/fixtures/owned-utxos.json")["owned_utxos"][0].clone(),
    )
    .unwrap()
}

/// UTxO `n`: `lovelace` more than the least its `tokens` need in one output (api_test's `parts_of_any_shape`).
fn utxo(n: u64, lovelace: u64, tokens: &[TokenAmount]) -> UtxoResponse {
    let pp = ProtocolParameters::from_koios(&params()).unwrap();
    let held = tokens.iter().fold(Assets::new(), |all, t| {
        all.add(
            Asset::new(
                t.policy_id.clone(),
                t.asset_name.clone(),
                t.quantity.parse().unwrap(),
            )
            .unwrap(),
        )
        .unwrap()
    });
    let least = wallet_minimum_lovelace_with_assets(&pp, held).unwrap();
    UtxoResponse {
        tx_hash: format!("{n:064x}"),
        value: (least + lovelace).to_string(),
        asset_list: Some(
            tokens
                .iter()
                .map(|t| Held {
                    decimals: 0,
                    quantity: t.quantity.clone(),
                    policy_id: t.policy_id.clone(),
                    asset_name: t.asset_name.clone(),
                    fingerprint: String::new(),
                })
                .collect(),
        ),
        ..base()
    }
}

/// Token T, `quantity` of it.
fn t(quantity: u64) -> TokenAmount {
    TokenAmount {
        policy_id: format!("{:056x}", 0xabc0_0000u64),
        asset_name: format!("{:064x}", 0x1000u64),
        quantity: quantity.to_string(),
    }
}

fn ada(first: u64, n: u64, lovelace: u64) -> Vec<UtxoResponse> {
    (first..first + n).map(|i| utxo(i, lovelace, &[])).collect()
}

fn transfer(utxos: Vec<UtxoResponse>, tokens: Vec<TokenAmount>) -> TransferRequest {
    let r = fixture("../extension/tests/fixtures/transfer-preprod.json");
    TransferRequest {
        network: "preprod".into(),
        params: params(),
        utxos,
        payments: vec![SeedelfPayment {
            to: r["to"].as_str().unwrap().into(),
            recipient: serde_json::from_value(r["recipient"].clone()).unwrap(),
            // Max.
            lovelace: None,
            tokens,
        }],
        classes: Default::default(),
        carry: false,
        seed: None,
        evaluation: None,
    }
}

/// What's wrong with Max in parts over `utxos`, asked for 15 T: `None` when it's refused in words naming the
/// token, or built with every UTxO of ADA alone spent.
fn wrong(case: &str, sk: blstrs::Scalar, utxos: &[UtxoResponse]) -> Option<String> {
    let policy = t(0).policy_id;
    match api::build_transfer_parts(sk, transfer(utxos.to_vec(), vec![t(15)])) {
        Err(e) => {
            let e = e.to_string();
            (e.contains("Not enough ADA") || !e.contains(&policy))
                .then(|| format!("{case}: Max in parts refused as {e:?}, though {} UTxOs of ADA alone are there", utxos.len()))
        }
        Ok(parts) => {
            let spent: Vec<&api::OutRef> = parts.iter().flat_map(|p| &p.inputs).collect();
            let ada_left: Vec<&UtxoResponse> = utxos
                .iter()
                .filter(|u| u.asset_list.iter().flatten().next().is_none())
                .filter(|u| {
                    !spent
                        .iter()
                        .any(|i| i.tx_hash == u.tx_hash && i.tx_index == u.tx_index)
                })
                .collect();
            if ada_left.is_empty() {
                return None;
            }
            let last = parts.last().unwrap();
            let paid: u64 = parts
                .iter()
                .map(|p| p.payments[0].lovelace.parse::<u64>().unwrap())
                .sum();
            let tokens: Vec<String> = parts
                .iter()
                .flat_map(|p| p.payments[0].tokens.iter().map(|x| x.quantity.clone()))
                .collect();
            let stranded: u64 = ada_left.iter().map(|u| u.value.parse::<u64>().unwrap()).sum();
            Some(format!(
                "{case}: Max in parts went as {} part(s) paying {paid} lovelace and T {tokens:?}, and left {} UTxOs \
                 of ADA alone ({stranded} lovelace) unspent; the last part says left = {}, left_why = {:?}",
                parts.len(),
                ada_left.len(),
                last.left,
                last.left_why,
            ))
        }
    }
}

#[test]
fn max_in_parts_asked_for_more_of_a_token_than_its_utxos_hold_is_refused_for_the_token_or_spends_the_ada() {
    let sk = seedelf_key_v1(PHRASE, 0).unwrap();
    let mut problems = Vec::new();

    // A: 10 T spendable (5 more held by a chain being sent, so the form offers 15), and 25 UTxOs of 10 ₳ alone.
    let mut some = vec![utxo(1, 1_000_000, &[t(10)])];
    some.extend(ada(100, 25, 10_000_000));
    // One transaction's Max refuses it in words, through core's `holding`.
    let one = api::build_transfer(sk, transfer(some.clone(), vec![t(15)]))
        .err()
        .map(|e| e.to_string())
        .unwrap_or_default();
    assert!(one.contains("holds only 10 of the token"), "one transaction's Max: {one:?}");
    problems.extend(wrong("A (10 of 15 T spendable)", sk, &some));

    // B: none of T spendable (all of it held by a chain being sent), and the same 25 UTxOs of ADA alone.
    let none = ada(100, 25, 10_000_000);
    let one = api::build_transfer(sk, transfer(none.clone(), vec![t(15)]))
        .err()
        .map(|e| e.to_string())
        .unwrap_or_default();
    assert!(one.contains("doesn't hold the token"), "one transaction's Max: {one:?}");
    problems.extend(wrong("B (no T spendable)", sk, &none));

    assert!(problems.is_empty(), "\n{}", problems.join("\n"));
}

//! Chunk 51, finding w1b#2: removing a Seedelf whose UTxO also holds another
//! token pays that token to the removal's destination, but `RemoveResult`,
//! which the worker turns into Remove's review, never names it.
//!
//! Anyone can make such a UTxO: the deployed policy (seedelf.ak at 5b82530)
//! checks only the minted name, and the wallet validator only the proof, so a
//! stranger can put a Seedelf plus tokens of their choice under a register the
//! user owns, and the wallet lists it among the user's Seedelfs.
//!
//! The right behaviour: the result names every token the removal moves, as
//! every other result whose change goes somewhere the user picked does
//! (`WithdrawResult`'s Max payment reports `built.change_tokens`). It fails
//! today because `remove_result` keeps only `built.change_lovelace`.

use pallas_traverse::MultiEraTx;
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_crypto::derivation::seedelf_key_v1;
use seedelf_koios::koios::{Asset, UtxoResponse};
use seedelf_wasm::api::{self, RemoveRequest};
use serde_json::Value;

const PHRASE: &str = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

/// A stranger's token, under a policy nothing else in the request uses.
const JUNK_NAME: &str = "6a756e6b"; // "junk"
const JUNK_QUANTITY: u64 = 100;

fn junk_policy() -> String {
    "cd".repeat(28)
}

fn fixture(path: &str) -> Value {
    let path = format!("{}/{path}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn params() -> Value {
    fixture("../../seedelf-core/tests/fixtures/epoch_params.json")[0].clone()
}

/// The fixture's Seedelf UTxO (the web-wallet register's, holding one Seedelf),
/// with 100 of the stranger's token beside it and 3 ₳, enough for an address
/// output carrying that token after the fee.
fn seedelf_with_junk() -> UtxoResponse {
    let owned: Vec<UtxoResponse> = serde_json::from_value(
        fixture("../extension/tests/fixtures/owned-utxos.json")["owned_utxos"].clone(),
    )
    .unwrap();
    let mut utxo = owned.into_iter().last().unwrap();
    assert_eq!(
        utxo.asset_list.as_ref().map(Vec::len),
        Some(1),
        "the fixture's Seedelf UTxO holds its Seedelf alone"
    );
    utxo.value = "3000000".into();
    utxo.asset_list.as_mut().unwrap().push(Asset {
        decimals: 0,
        quantity: JUNK_QUANTITY.to_string(),
        policy_id: junk_policy(),
        asset_name: JUNK_NAME.into(),
        fingerprint: String::new(),
    });
    utxo
}

/// The account's receive address 0/0 on preprod: where withdraw.ts's
/// `buildRemove` sends a removal "to the account".
fn own_address() -> String {
    CardanoAccount::from_phrase(PHRASE, 0)
        .unwrap()
        .base_address(true, Role::Receive, 0)
        .unwrap()
        .to_bech32()
        .unwrap()
}

/// How much of the junk token the transaction's outputs pay to `to`.
fn junk_paid_to(tx_cbor: &str, to: &str) -> u64 {
    let bytes = hex::decode(tx_cbor).unwrap();
    let tx = MultiEraTx::decode(&bytes).unwrap();
    let policy = junk_policy();
    let name = hex::decode(JUNK_NAME).unwrap();
    let mut paid = 0;
    for output in tx.outputs() {
        if output.address().unwrap().to_bech32().unwrap() != to {
            continue;
        }
        let value = output.value();
        for group in value.assets() {
            if hex::encode(group.policy()) != policy {
                continue;
            }
            for asset in group.assets() {
                if asset.name() == name.as_slice() {
                    paid += asset.output_coin().unwrap();
                }
            }
        }
    }
    paid
}

#[test]
fn a_removal_names_the_tokens_it_moves() {
    let sk = seedelf_key_v1(PHRASE, 0).unwrap();
    let to = own_address();
    let request = RemoveRequest {
        network: "preprod".into(),
        params: params(),
        utxo: seedelf_with_junk(),
        to: Some(to.clone()),
        seed: None,
        evaluation: None,
    };
    // Built as the worker builds it: measured in the wallet, then shown.
    let result = api::build_remove(sk, request).unwrap();

    // What the transaction does: the stranger's 100 tokens go to `to` with
    // the ADA. (This holds today.)
    assert_eq!(
        junk_paid_to(&result.tx_cbor, &to),
        JUNK_QUANTITY,
        "the removal pays the UTxO's other token to its destination"
    );

    // What the worker and the review get: every field but the transaction's
    // own bytes, hash and seed. It must name the token it moves.
    let mut shown = serde_json::to_value(&result).unwrap();
    let fields = shown.as_object_mut().unwrap();
    for raw in ["txCbor", "txHash", "seed"] {
        fields.remove(raw);
    }
    let shown = shown.to_string();
    assert!(
        shown.contains(&junk_policy()) && shown.contains(JUNK_NAME),
        "the removal moves {JUNK_QUANTITY} of {}.{JUNK_NAME} to {to}, \
         but its result names no token: {shown}",
        junk_policy()
    );
}

//! Chunk 51, finding w2#1: a certificate under a script's stake credential is
//! counted as a signature someone else must give (`others_sign`), so the
//! transaction is never `complete`. Without partialSign it is refused before
//! the window opens; with it the window says others sign too.
//!
//! No key signs for a script's credential. Conway's ledger asks a certificate
//! for `credKeyHashWitness cred`, which is Nothing for a script, and Shelley's
//! registration (certificate 0, `ConwayRegCert _ SNothing`) needs no witness
//! of any kind. seedelf-core says the same (`staking.rs` `is_scripts`: "a
//! script's credential, which no key signs for"), and the connector already
//! counts no one for a script's zero withdrawal or a script DRep's certificate:
//! the two controls below, which pass today.
//!
//! The transaction: the account's 5 ₳ at 0/0 in, 2.8 ₳ back to 0/0, a 0.2 ₳
//! fee, and one certificate under a script's credential, sent without
//! partialSign.

use pallas_addresses::Address;
use pallas_codec::utils::{Bytes, NonEmptyKeyValuePairs, NonEmptySet, Nullable, Set};
use pallas_crypto::hash::Hash;
use pallas_primitives::{Fragment, StakeCredential, TransactionInput, conway};
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_wasm::cip30::{self, KeyPath, KoiosRow, TxRequest};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const TX_A: &str = "1111111111111111111111111111111111111111111111111111111111111111";
const SCRIPT: [u8; 28] = [6; 28];

fn account() -> CardanoAccount {
    CardanoAccount::from_phrase(PHRASE, 0).unwrap()
}

fn ours() -> Address {
    account().base_address(true, Role::Receive, 0).unwrap()
}

fn script() -> StakeCredential {
    StakeCredential::ScriptHash(Hash::new(SCRIPT))
}

/// The script's reward address on preprod: header 0xf0, then its hash.
fn script_reward_account() -> Bytes {
    let mut bytes = vec![0xf0];
    bytes.extend_from_slice(&SCRIPT);
    Bytes::from(bytes)
}

fn tx_hex(
    certificates: Vec<conway::Certificate>,
    withdrawals: Vec<(Bytes, u64)>,
) -> String {
    let body = conway::TransactionBody {
        inputs: Set::from(vec![TransactionInput {
            transaction_id: Hash::new(hex::decode(TX_A).unwrap().try_into().unwrap()),
            index: 1,
        }]),
        outputs: vec![conway::PseudoTransactionOutput::PostAlonzo(
            conway::PostAlonzoTransactionOutput {
                address: Bytes::from(ours().to_vec()),
                value: conway::Value::Coin(2_800_000),
                datum_option: None,
                script_ref: None,
            },
        )],
        fee: 200_000,
        ttl: Some(99_999_999),
        certificates: NonEmptySet::try_from(certificates).ok(),
        withdrawals: NonEmptyKeyValuePairs::try_from(withdrawals).ok(),
        auxiliary_data_hash: None,
        validity_interval_start: None,
        mint: None,
        script_data_hash: None,
        collateral: None,
        required_signers: None,
        network_id: None,
        collateral_return: None,
        total_collateral: None,
        reference_inputs: None,
        voting_procedures: None,
        proposal_procedures: None,
        treasury_value: None,
        donation: None,
    };
    let tx = conway::Tx {
        transaction_body: body,
        transaction_witness_set: conway::WitnessSet {
            vkeywitness: None,
            native_script: None,
            bootstrap_witness: None,
            plutus_v1_script: None,
            plutus_data: None,
            redeemer: None,
            plutus_v2_script: None,
            plutus_v3_script: None,
        },
        success: true,
        auxiliary_data: Nullable::Null,
    };
    hex::encode(tx.encode_fragment().unwrap())
}

/// Found by the extension: the account's 5 ₳ at 0/0.
fn row() -> KoiosRow {
    serde_json::from_value(serde_json::json!({
        "tx_hash": TX_A,
        "tx_index": 1,
        "address": ours().to_bech32().unwrap(),
        "value": "5000000",
        "asset_list": [],
    }))
    .unwrap()
}

fn request(tx: String) -> TxRequest {
    TxRequest {
        network: "preprod".into(),
        tx_cbor: tx,
        keys: (0..3)
            .flat_map(|index| [KeyPath { role: 0, index }, KeyPath { role: 1, index }])
            .collect(),
        inputs: vec![row()],
        // Mesh's default.
        partial_sign: false,
        stake_index: 0,
        stake_deposit: None,
        governance: false,
    }
}

#[test]
fn a_scripts_stake_certificate_needs_no_one_elses_signature() {
    let pool = Hash::new([7; 28]);
    let cases: Vec<(&str, Vec<conway::Certificate>, Vec<(Bytes, u64)>)> = vec![
        // Controls: what the connector already counts as needing no key.
        (
            "control: a script's zero withdrawal",
            vec![],
            vec![(script_reward_account(), 0)],
        ),
        (
            "control: a script DRep's registration",
            vec![conway::Certificate::RegDRepCert(
                script(),
                500_000_000,
                Nullable::Null,
            )],
            vec![],
        ),
        // The finding's shapes.
        (
            "Shelley's registration, cert 0 (the ledger asks no witness at all)",
            vec![conway::Certificate::StakeRegistration(script())],
            vec![],
        ),
        (
            "Conway's registration, cert 7",
            vec![conway::Certificate::Reg(script(), 2_000_000)],
            vec![],
        ),
        (
            "a delegation, cert 2",
            vec![conway::Certificate::StakeDelegation(script(), pool)],
            vec![],
        ),
        (
            "a vote delegation, cert 9",
            vec![conway::Certificate::VoteDeleg(
                script(),
                conway::DRep::Abstain,
            )],
            vec![],
        ),
    ];

    let mut wrong = Vec::new();
    for (name, certificates, withdrawals) in cases {
        let tx = tx_hex(certificates, withdrawals);
        let summary = cip30::inspect_tx(&account(), &request(tx.clone())).unwrap();
        let signed = cip30::sign_tx(&account(), &request(tx));
        let outcome = match &signed {
            Ok(s) => format!("signed by {:?}", s.summary.signs),
            Err(e) => format!("refused: {e}"),
        };
        println!(
            "{name}: others_sign {}, complete {}, {outcome}",
            summary.others_sign, summary.complete
        );
        let right = summary.others_sign == 0
            && summary.complete
            && signed.is_ok_and(|s| s.summary.signs == vec!["0/0".to_string()]);
        if !right {
            wrong.push(name);
        }
    }
    assert!(
        wrong.is_empty(),
        "needs no one else's signature, but counted as needing one: {wrong:#?}"
    );
}

//! Chunk 51, finding w2#2: the connector window names an output "Seedelf
//! Wallet's contract" by its payment part's 28 bytes alone. A KEY address whose
//! key hash is the contract's script hash matches too, though no key has that
//! hash: what's paid there is burned, not paid to a Seedelf. Transaction
//! details (`decode.rs`) checks `is_script()` and calls it a plain key address.
//! This asserts the right behaviour, so it fails while the bug is there.

use pallas_addresses::{
    Address, Network, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
};
use pallas_codec::utils::{Bytes, CborWrap, Nullable, Set};
use pallas_crypto::hash::Hash;
use pallas_primitives::{Fragment, PlutusData, TransactionInput, conway};
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_wasm::cip30::{self, KeyPath, KoiosRow, TxRequest};
use seedelf_wasm::decode::decode_tx;

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const TX_A: &str = "1111111111111111111111111111111111111111111111111111111111111111";
/// A register datum: constructor 0 with the G1 generator and a test vector's public value, as cip30_test.rs has it.
const REGISTER_DATUM: &str = "d8799f583097f1d3a73197d7942695638c4fa9ac0fc3688c4f9774b905a14e3a3f171bac586c55e83ff97a1aeffb3af00adb22c6bb583082dcf46570656ca0d6fb143b8e7c2816b20cb1a6434ca4c8c95c624443c22c9e1d40ad0df5de088b19a4b44b685b8475ff";

fn account() -> CardanoAccount {
    CardanoAccount::from_phrase(PHRASE, 0).unwrap()
}

fn keys() -> Vec<KeyPath> {
    (0..3)
        .flat_map(|index| [KeyPath { role: 0, index }, KeyPath { role: 1, index }])
        .collect()
}

fn ours(role: Role, index: u32) -> Address {
    account().base_address(true, role, index).unwrap()
}

fn row(tx: &str, index: u64, address: &Address, lovelace: u64) -> KoiosRow {
    serde_json::from_value(serde_json::json!({
        "tx_hash": tx,
        "tx_index": index,
        "address": address.to_bech32().unwrap(),
        "value": lovelace.to_string(),
        "asset_list": [],
    }))
    .unwrap()
}

fn input(tx: &str, index: u64) -> TransactionInput {
    TransactionInput {
        transaction_id: Hash::new(hex::decode(tx).unwrap().try_into().unwrap()),
        index,
    }
}

fn out(address: &Address, lovelace: u64, datum: Option<&str>) -> conway::TransactionOutput {
    conway::PseudoTransactionOutput::PostAlonzo(conway::PostAlonzoTransactionOutput {
        address: Bytes::from(address.to_vec()),
        value: conway::Value::Coin(lovelace),
        datum_option: datum.map(|d| {
            conway::PseudoDatumOption::Data(CborWrap(
                PlutusData::decode_fragment(&hex::decode(d).unwrap()).unwrap(),
            ))
        }),
        script_ref: None,
    })
}

fn tx_hex(inputs: Vec<TransactionInput>, outputs: Vec<conway::TransactionOutput>) -> String {
    let body = conway::TransactionBody {
        inputs: Set::from(inputs),
        outputs,
        fee: 200_000,
        ttl: Some(99_999_999),
        certificates: None,
        withdrawals: None,
        auxiliary_data_hash: None,
        validity_interval_start: None,
        mint: None,
        script_data_hash: None,
        collateral: None,
        required_signers: None,
        network_id: None,
        collateral_return: None,
        total_collateral: None,
        reference_inputs: None,
        voting_procedures: None,
        proposal_procedures: None,
        treasury_value: None,
        donation: None,
    };
    let tx = conway::Tx {
        transaction_body: body,
        transaction_witness_set: conway::WitnessSet {
            vkeywitness: None,
            native_script: None,
            bootstrap_witness: None,
            plutus_v1_script: None,
            plutus_data: None,
            redeemer: None,
            plutus_v2_script: None,
            plutus_v3_script: None,
        },
        success: true,
        auxiliary_data: Nullable::Null,
    };
    hex::encode(tx.encode_fragment().unwrap())
}

#[test]
fn a_key_address_with_the_contracts_hash_is_not_seedelf_wallets_contract() {
    let contract_hash = seedelf_core::constants::get_config(1, true)
        .unwrap()
        .contract
        .wallet_contract_hash;
    // The contract itself: its hash as a SCRIPT payment part.
    let contract = seedelf_core::address::wallet_contract(true, contract_hash);
    // The same 28 bytes as a KEY payment part, enterprise, on preprod (header
    // 0x60): an address no key spends, so what goes there is gone for good.
    let burn = Address::Shelley(ShelleyAddress::new(
        Network::Testnet,
        ShelleyPaymentPart::Key(Hash::new(contract_hash)),
        ShelleyDelegationPart::Null,
    ));
    assert_eq!(burn.to_vec()[0], 0x60, "an enterprise key address on a test network");
    assert_ne!(burn.to_vec(), contract.to_vec());

    // The account's 10 ₳ pays 2 ₳ there under a register, 1.5 ₳ there with no
    // datum, 2 ₳ into the real contract under a register, and its change.
    let rows = vec![row(TX_A, 0, &ours(Role::Receive, 0), 10_000_000)];
    let tx = tx_hex(
        vec![input(TX_A, 0)],
        vec![
            out(&burn, 2_000_000, Some(REGISTER_DATUM)),
            out(&burn, 1_500_000, None),
            out(&contract, 2_000_000, Some(REGISTER_DATUM)),
            out(&ours(Role::Change, 0), 4_300_000, None),
        ],
    );

    // Transaction details reads the key address as what it is: a key's, not
    // the contract's (decode.rs checks is_script()). Holds today.
    let detail = decode_tx("preprod", &tx).unwrap();
    assert_eq!(detail.outputs[0].address.payment.as_deref(), Some("key"));
    assert!(!detail.outputs[0].address.seedelf);
    assert!(!detail.outputs[1].address.seedelf);
    assert!(detail.outputs[2].address.seedelf);

    let request = TxRequest {
        network: "preprod".into(),
        tx_cbor: tx,
        keys: keys(),
        inputs: rows,
        partial_sign: false,
        stake_index: 0,
        stake_deposit: None,
        governance: false,
    };
    let summary = cip30::inspect_tx(&account(), &request).unwrap();
    assert_eq!(summary.paid.len(), 3, "the change is the account's own");
    assert_eq!(summary.paid[0].address, burn.to_bech32().unwrap());
    // Not a script, so no contract holds it.
    assert!(!summary.paid[0].script);
    assert!(!summary.paid[1].script);
    // The real contract output still reads as a Seedelf payment.
    assert!(summary.paid[2].script);
    assert_eq!(summary.paid[2].seedelf.as_deref(), Some("register"));
    // The window must not call a key address Seedelf Wallet's contract:
    // "register" shows "Seedelf Wallet's contract" and "It pays a Seedelf…";
    // "none" warns "…without a register: whatever goes there, anyone can take."
    assert_eq!(
        summary.paid[0].seedelf, None,
        "a key address under the register datum is labelled Seedelf Wallet's contract"
    );
    assert_eq!(
        summary.paid[1].seedelf, None,
        "a key address with no datum gets the contract's no-register warning"
    );
}

//! Chunk 51, finding w2#4: `getUtxos` hands a site the account's UTxO without
//! the reference script it carries on chain. The worker passes WebAssembly the
//! Koios row with its `reference_script` kept (`trimmed`, koios.ts), but
//! `KoiosRow` has no field for it and `utxo_cbor` writes keys 0 to 2 only (or
//! the legacy array). A site that prices its fee from the UTxO it was handed
//! leaves out Conway's fee for a reference script on a spent input, and the
//! node refuses the signed transaction (`FeeTooSmallUTxO`). This asserts the
//! right behaviour, the output as the ledger holds it, so it fails while the
//! bug is there.

use pallas_codec::minicbor;
use pallas_codec::utils::CborWrap;
use pallas_crypto::hash::{Hash, Hasher};
use pallas_primitives::{Fragment, TransactionInput, conway};
use seedelf_core::build::reference_script_fee;
use seedelf_crypto::cardano::{CardanoAccount, Role};
use seedelf_koios::koios::ProtocolParameters;
use seedelf_wasm::cip30::{self, KoiosRow};

const PHRASE: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";
const TX_A: &str = "1111111111111111111111111111111111111111111111111111111111111111";

/// Mainnet's and preprod's fee parameters, 15 lovelace a byte of reference script.
fn params() -> ProtocolParameters {
    ProtocolParameters::from_koios(&serde_json::json!({
        "min_fee_a": 44, "min_fee_b": 155381, "coins_per_utxo_size": "4310",
        "key_deposit": "2000000", "price_mem": 0.0577, "price_step": 0.0000721,
        "min_fee_ref_script_cost_per_byte": 15,
        "cost_models": { "PlutusV3": [] },
    }))
    .unwrap()
}

#[test]
fn a_utxo_carrying_a_reference_script_is_handed_over_with_it() {
    // A stranger's native script: any of 15 keys, 483 bytes. Anyone can pay
    // the account's 0/0 an output carrying it, for its minimum ADA.
    let native = conway::NativeScript::ScriptAny(
        (1..=15u8)
            .map(|i| conway::NativeScript::ScriptPubkey(Hash::new([i; 28])))
            .collect(),
    );
    let script = native.encode_fragment().unwrap();
    assert_eq!(script.len(), 483);
    let address = CardanoAccount::from_phrase(PHRASE, 0)
        .unwrap()
        .base_address(true, Role::Receive, 0)
        .unwrap();

    // The row as the worker hands it to `cip30Utxos` (dapp.ts `encode`): Koios's
    // `credential_utxos` row, `trimmed`, its reference script kept.
    let row: KoiosRow = serde_json::from_value(serde_json::json!({
        "tx_hash": TX_A,
        "tx_index": 0,
        "address": address.to_bech32().unwrap(),
        "value": "5000000",
        "stake_address": null,
        "payment_cred": null,
        "block_height": 1,
        "inline_datum": null,
        "datum_hash": null,
        "asset_list": [],
        "reference_script": {
            "hash": hex::encode(Hasher::<224>::hash_tagged(&script, 0)),
            "size": script.len(),
            "type": "timelock",
            "bytes": hex::encode(&script),
        },
    }))
    .unwrap();

    let bytes = cip30::utxo_cbor(&row).unwrap();
    let mut d = minicbor::Decoder::new(&bytes);
    assert_eq!(d.array().unwrap(), Some(2));
    let input: TransactionInput = d.decode().unwrap();
    assert_eq!(hex::encode(input.transaction_id), TX_A);
    let output: conway::TransactionOutput = d.decode().unwrap();
    let script_ref = match output {
        conway::PseudoTransactionOutput::PostAlonzo(o) => o.script_ref,
        conway::PseudoTransactionOutput::Legacy(_) => None,
    };

    // What a site's fee leaves out when it can't see the script (Conway's
    // reference-script fee, the wallet's own reckoning of it).
    let short = reference_script_fee(&params(), script.len() as u64).unwrap();
    assert_eq!(short, 7_245);
    let Some(CborWrap(conway::PseudoScript::NativeScript(handed))) = script_ref else {
        panic!(
            "getUtxos hands the site {} without the reference script it holds on chain: \
             a fee priced from it is {short} lovelace short, and the node refuses the transaction",
            hex::encode(&bytes)
        );
    };
    assert_eq!(handed.encode_fragment().unwrap(), script);
}

// Chunk 51, w2#5 (the verifier's test). A stranger mints one token of their
// own three times, each the most one transaction can mint (2^63 − 1: Conway's
// `mint = multiasset<nonZeroInt64>`), into three outputs at the account's
// 0/0. Each output holds a u64's worth at most, as the ledger keeps it, but
// together they hold 3 × (2^63 − 1) ≈ 2.77 × 10^19, past a u64. The worker's
// getBalance (dapp.ts `balance()`) sums the account's available UTxOs in
// BigInt and hands the total to WebAssembly's cip30Value (cip30.rs
// `value_cbor`), which parses each quantity as a u64 and refuses the whole
// call. Every site connected to the account then hears InternalError for
// getBalance, until the user locks one of those UTxOs.
//
// What's right: getBalance still answers with a CIP-30 Value, its ADA the
// account's, the account's other tokens as before, and no quantity past what
// a Value holds (the stranger's token capped or left out: the owner's call).
// Driven through the worker with the real WebAssembly, so a fix in either
// place passes it.

import { describe, expect, it } from "vitest";

import type { DappSession } from "../src/background/dapp";
import type { KoiosUtxo } from "../src/background/koios";
import { koiosPreprod, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const phrase12 = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
/** The 12-word account's `0/0`, where the stranger pays. */
const OWN = phrase12.preprod.receive_0 as string;
/** The most one transaction can mint of a token. */
const MOST_ONE_MINT = 2n ** 63n - 1n;
/** The most a CIP-30 Value (and a ledger output) holds of a token. */
const U64_MAX = 2n ** 64n - 1n;
const JUNK_POLICY = "ee".repeat(28);
const JUNK_NAME = "6a756e6b"; // "junk"

type Read = { lovelace: string; tokens: Array<{ policyId: string; assetName: string; quantity: string }> };

describe("chunk 51 w2#5: getBalance once a stranger's token adds up past a u64", () => {
  it("still answers every connected site with the account's Value", { timeout: 30_000 }, async () => {
    const t = testBalances();
    await t.wallet.create(phrase12.phrase, PASSWORD);
    await t.preferences.set({ dappConnector: true, spendRewards: false });
    const s: DappSession = { id: "r51-w2-5", origin: "https://app.example.com", title: "Example" };
    const enabling = t.dapp.call(s, "enable", []);
    for (let i = 0; i < 200 && t.dapp.approvals().length !== 1; i++) await new Promise((r) => setTimeout(r, 0));
    expect(t.dapp.approvals()).toHaveLength(1);
    await t.dapp.answer(t.dapp.approvals()[0]!.id, true);
    expect(await enabling).toBe(true);

    const { wasm } = t.deps;
    const read = async (): Promise<Read> => JSON.parse(wasm.cip30ReadValue((await t.dapp.call(s, "getBalance", [])) as string));
    const before = await read();
    expect(before.tokens.some((x) => x.policyId === JUNK_POLICY)).toBe(false);

    // The stranger's outputs at 0/0: 1.5 ₳ and the most one mint makes, each from its own mint.
    const template = Object.values(koiosPreprod.accounts)
      .flatMap((a) => a.account_utxos)
      .find((u) => u.address === OWN)!;
    const junk = (n: number): KoiosUtxo => ({
      ...template,
      tx_hash: `e${n}`.repeat(32),
      tx_index: 0,
      value: "1500000",
      asset_list: [
        { policy_id: JUNK_POLICY, asset_name: JUNK_NAME, quantity: MOST_ONE_MINT.toString(), decimals: 0, fingerprint: "asset1junk" },
      ],
      block_height: 1,
    });

    // Two of them: 2^64 − 2, which a u64 holds. Answered today, the total exact.
    t.koios.addedToAccounts.push(junk(1), junk(2));
    t.clock.now += 31_000; // past the connector's 30 s reading
    const two = await read();
    expect(BigInt(two.lovelace)).toBe(BigInt(before.lovelace) + 3_000_000n);
    expect(two.tokens.find((x) => x.policyId === JUNK_POLICY)?.quantity).toBe((2n * MOST_ONE_MINT).toString());

    // The third: 3 × (2^63 − 1), past a u64. Today getBalance throws here
    // ("a token quantity isn't a whole number: \"27670116110564327421\""),
    // which a site hears as InternalError (sw.ts).
    t.koios.addedToAccounts.push(junk(3));
    t.clock.now += 31_000;
    const three = await read();
    expect(BigInt(three.lovelace)).toBe(BigInt(before.lovelace) + 4_500_000n);
    // The account's own tokens, as before.
    for (const token of before.tokens) expect(three.tokens).toContainEqual(token);
    // Nothing past what a CIP-30 Value holds.
    for (const token of three.tokens) expect(BigInt(token.quantity) <= U64_MAX).toBe(true);
  });
});

